--airspace.airspace_view

create or replace view airspace.airspace_view as
select distinct on (aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number)
    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_feature.hjid::text || '_' || aixm.aixm_timeslice.hjid::text) row,
    aixm.aixm_message.hjid as message_hjid,
    aixm.aixm_message.id as message_id,
    aixm.aixm_message.identifier as message_tidentifier,
    aixm.aixm_feature.hjid,
    aixm.aixm_feature.id as feature_id,
    aixm.aixm_feature.identifier,
    aixm.aixm_timeslice.id as timeslice_id,
    aixm.aixm_timeslice.hjid as timeslice_hjid,
    aixm.aixm_timeslice.interpretation,
    aixm.aixm_timeslice.sequence_number,
    aixm.aixm_timeslice.correction_number,
    aixm.aixm_timeslice.feature_lifetime_begin,
    aixm.aixm_timeslice.feature_lifetime_end,
    aixm.aixm_timeslice.valid_time_begin,
    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded CodeAirspaceType for gettypeitem,
    airspace.airspace_t.type::text,
    airspace.airspace_t.typenilreason::text,
    -- embedded CodeAirspaceDesignatorType for getdesignatoritem,
    airspace.airspace_t.designator::text,
    airspace.airspace_t.designatornilreason::text,
    -- embedded TextNameType for getlocaltypeitem,
    airspace.airspace_t.localtype::text,
    airspace.airspace_t.localtypenilreason::text,
    -- embedded TextNameType for getaixmnameitem,
    airspace.airspace_t.name::text,
    airspace.airspace_t.namenilreason::text,
    -- embedded CodeYesNoType for getdesignatoricaoitem,
    airspace.airspace_t.designatoricao::text,
    airspace.airspace_t.designatoricaonilreason::text,
    -- embedded CodeMilitaryOperationsType for getcontroltypeitem,
    airspace.airspace_t.controltype::text,
    airspace.airspace_t.controltypenilreason::text,
    -- embedded ValFLType for getupperlowerseparationitem,
    airspace.airspace_t.upperlowerseparation::text,
    airspace.airspace_t.upperlowerseparationuom::text,
    airspace.airspace_t.upperlowerseparationnilreason::text,
    -- composed RoutePropertyType for protected_route,
    jsonb_build_object('href', route_fvjqza.href,
    'nilreason', route_fvjqza.nil_reason,
    'title', route_fvjqza.simple_link_title) AS protected_route,
    -- composed AirspaceLayerClassPropertyType for clazz,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from airspace.arspctmslctp_clss_link join aixm.aixm_property on airspace.arspctmslctp_clss_link.class_hjid = aixm.aixm_property.hjid where airspace.airspace_t.hjid = airspace.arspctmslctp_clss_link.airspace_t_hjid ) as clazz,
    -- composed AirspaceGeometryComponentPropertyType for geometry_component,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from airspace.arspctmslctp_gmtrcmpnnt_link join aixm.aixm_property on airspace.arspctmslctp_gmtrcmpnnt_link.geometrycomponent_hjid = aixm.aixm_property.hjid where airspace.airspace_t.hjid = airspace.arspctmslctp_gmtrcmpnnt_link.airspace_t_hjid ) as geometry_component,
    -- composed AirspaceActivationPropertyType for activation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from airspace.arspctmslctp_actvtn_link join aixm.aixm_property on airspace.arspctmslctp_actvtn_link.activation_hjid = aixm.aixm_property.hjid where airspace.airspace_t.hjid = airspace.arspctmslctp_actvtn_link.airspace_t_hjid ) as activation,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from airspace.arspctmslctp_annttn_link join aixm.aixm_property on airspace.arspctmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where airspace.airspace_t.hjid = airspace.arspctmslctp_annttn_link.airspace_t_hjid ) as annotation
from aixm.aixm_feature
inner join airspace.airspace_f on aixm.aixm_feature.hjid = airspace.airspace_f.hjid
inner join airspace.airspace_tp on aixm.aixm_feature.hjid = airspace.airspace_tp.timeslice_hjid
inner join airspace.airspace_t on airspace.airspace_tp.airspacetimeslice_hjid = airspace.airspace_t.hjid
inner join aixm.aixm_timeslice on airspace.airspace_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed RoutePropertyType for protected_route
left join airspace.arspctmslctp_prtctdrt_link airspace_tmefhp on airspace.airspace_t.hjid = airspace_tmefhp.airspace_t_hjid
left join route.route_p route_fvjqza on airspace_tmefhp.protectedroute_hjid = route_fvjqza.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

