-- composed TerminalSegmentPointPropertyType for end_point
left join procedure.arrvllgtmslctp_endpnt_link procedure_woumiy on procedure.arrivalleg_t.hjid = procedure_woumiy.arrivalleg_t_hjid
left join aixm.aixm_property aixm_property_uuwkfr on procedure_woumiy.endpoint_hjid = aixm_property_uuwkfr.hjid
-- composed AIXMCurvePropertyType for trajectory
left join procedure.arrvllgtmslctp_trjctr_link procedure_snkref on procedure.arrivalleg_t.hjid = procedure_snkref.arrivalleg_t_hjid
left join gml.aixm_curve_pt_view aixm_curve_pt_view_rphkil on procedure_snkref.trajectory_hjid = aixm_curve_pt_view_rphkil.hjid
-- composed TerminalSegmentPointPropertyType for arc_centre
left join procedure.arrvllgtmslctp_arccntr_link procedure_hlbufm on procedure.arrivalleg_t.hjid = procedure_hlbufm.arrivalleg_t_hjid
left join aixm.aixm_property aixm_property_hydolc on procedure_hlbufm.arccentre_hjid = aixm_property_hydolc.hjid
-- composed HoldingUsePropertyType for holding
left join procedure.arrvllgtmslctp_hldng_link procedure_dqouxo on procedure.arrivalleg_t.hjid = procedure_dqouxo.arrivalleg_t_hjid
left join aixm.aixm_property aixm_property_vxrjbu on procedure_dqouxo.holding_hjid = aixm_property_vxrjbu.hjid
-- composed DistancePropertyType for limiting_distance
left join procedure.arrvllgtmslctp_lmtngdstnc_link procedure_steimo on procedure.arrivalleg_t.hjid = procedure_steimo.arrivalleg_t_hjid
left join aixm.aixm_property aixm_property_vcmrcx on procedure_steimo.limitingdistance_hjid = aixm_property_vcmrcx.hjid
-- composed AnglePropertyType for limiting_angle
left join procedure.arrvllgtmslctp_lmtngangl_link procedure_eromtm on procedure.arrivalleg_t.hjid = procedure_eromtm.arrivalleg_t_hjid
left join aixm.aixm_property aixm_property_jgaxrf on procedure_eromtm.limitingangle_hjid = aixm_property_jgaxrf.hjid
-- composed StandardInstrumentArrivalPropertyType for arrival
left join procedure.arrvllgtmslctp_arrvl_link procedure_aosdpn on procedure.arrivalleg_t.hjid = procedure_aosdpn.arrivalleg_t_hjid
left join procedure.standardinstrumentarrival_p standardinstrumentarrival_pfxaof on procedure_aosdpn.arrival_hjid = standardinstrumentarrival_pfxaof.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

--airspace.authorityforairspace_view

create or replace view airspace.authorityforairspace_view as
select distinct on (aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number)
    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_feature.hjid::text || '_' || aixm.aixm_timeslice.hjid::text) row,
    aixm.aixm_message.hjid as message_hjid,
    aixm.aixm_message.id as message_id,
    aixm.aixm_message.identifier as message_tidentifier,
    aixm.aixm_feature.hjid,
    aixm.aixm_feature.id as feature_id,
    aixm.aixm_feature.identifier,
    aixm.aixm_timeslice.id as timeslice_id,
    aixm.aixm_timeslice.hjid as timeslice_hjid,
    aixm.aixm_timeslice.interpretation,
    aixm.aixm_timeslice.sequence_number,
    aixm.aixm_timeslice.correction_number,
    aixm.aixm_timeslice.feature_lifetime_begin,
    aixm.aixm_timeslice.feature_lifetime_end,
    aixm.aixm_timeslice.valid_time_begin,
    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded CodeAuthorityType for gettypeitem,
    airspace.authorityforairspace_t.type::text,
    airspace.authorityforairspace_t.typenilreason::text,
    -- composed OrganisationAuthorityPropertyType for responsible_organisation,
    jsonb_build_object('href', organisationauthority_ftxnpg.href,
    'nilreason', organisationauthority_ftxnpg.nil_reason,
    'title', organisationauthority_ftxnpg.simple_link_title) AS responsible_organisation,
    -- composed AirspacePropertyType for assigned_airspace,
    jsonb_build_object('href', airspace_felmxd.href,
    'nilreason', airspace_felmxd.nil_reason,
    'title', airspace_felmxd.simple_link_title) AS assigned_airspace,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from airspace.athrtfrarspctmslctp_annttn_link join aixm.aixm_property on airspace.athrtfrarspctmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where airspace.authorityforairspace_t.hjid = airspace.athrtfrarspctmslctp_annttn_link.authorityforairspace_t_hjid ) as annotation
from aixm.aixm_feature
inner join airspace.authorityforairspace_f on aixm.aixm_feature.hjid = airspace.authorityforairspace_f.hjid
inner join airspace.authorityforairspace_tp on aixm.aixm_feature.hjid = airspace.authorityforairspace_tp.timeslice_hjid
inner join airspace.authorityforairspace_t on airspace.authorityforairspace_tp.authorityforairspacetimeslice_hjid = airspace.authorityforairspace_t.hjid
inner join aixm.aixm_timeslice on airspace.authorityforairspace_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed OrganisationAuthorityPropertyType for responsible_organisation
left join airspace.athrtfrarspctmslctp_rspnsblorgnstn_link airspace_yhqkuh on airspace.authorityforairspace_t.hjid = airspace_yhqkuh.authorityforairspace_t_hjid
left join organisation.organisationauthority_p organisationauthority_ftxnpg on airspace_yhqkuh.responsibleorganisation_hjid = organisationauthority_ftxnpg.hjid
-- composed AirspacePropertyType for assigned_airspace
left join airspace.athrtfrarspctmslctp_assgndarspc_link airspace_tdfuzm on airspace.authorityforairspace_t.hjid = airspace_tdfuzm.authorityforairspace_t_hjid
left join airspace.airspace_p airspace_felmxd on airspace_tdfuzm.assignedairspace_hjid = airspace_felmxd.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

