--route.changeoverpoint_view

create or replace view route.changeoverpoint_view as
select distinct on (aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number)
    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_feature.hjid::text || '_' || aixm.aixm_timeslice.hjid::text) row,
    aixm.aixm_message.hjid as message_hjid,
    aixm.aixm_message.id as message_id,
    aixm.aixm_message.identifier as message_tidentifier,
    aixm.aixm_feature.hjid,
    aixm.aixm_feature.id as feature_id,
    aixm.aixm_feature.identifier,
    aixm.aixm_timeslice.id as timeslice_id,
    aixm.aixm_timeslice.hjid as timeslice_hjid,
    aixm.aixm_timeslice.interpretation,
    aixm.aixm_timeslice.sequence_number,
    aixm.aixm_timeslice.correction_number,
    aixm.aixm_timeslice.feature_lifetime_begin,
    aixm.aixm_timeslice.feature_lifetime_end,
    aixm.aixm_timeslice.valid_time_begin,
    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded ValDistanceType for getdistanceitem,
    route.changeoverpoint_t.distance::text,
    route.changeoverpoint_t.distanceuom::text,
    route.changeoverpoint_t.distanceaccuracy::text,
    route.changeoverpoint_t.distancenilreason::text,
    -- composed geometry AIXMPointPropertyType for location_position,
    aixm_point_pt_view_flutiv.geom as location_position_geom,
    jsonb_build_object('hjid', aixm_point_pt_view_flutiv.hjid,
    'id', aixm_point_pt_view_flutiv.id,
    'horizontalaccuracy', aixm_point_pt_view_flutiv.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_point_pt_view_flutiv.horizontalaccuracy_uom,
    'horizontalaccuracy_accuracy', aixm_point_pt_view_flutiv.horizontalaccuracy_accuracy,
    'horizontalaccuracy_nilreason', aixm_point_pt_view_flutiv.horizontalaccuracy_nilreason) AS location_position,
    -- composed DesignatedPointPropertyType for location_fix_designated_point,
    jsonb_build_object('href', designatedpoint_bjxrik.href,
    'nilreason', designatedpoint_bjxrik.nil_reason,
    'title', designatedpoint_bjxrik.simple_link_title) AS location_fix_designated_point,
    -- composed NavaidPropertyType for location_navaid_system,
    jsonb_build_object('href', navaid_ohcpag.href,
    'nilreason', navaid_ohcpag.nil_reason,
    'title', navaid_ohcpag.simple_link_title) AS location_navaid_system,
    -- composed RunwayCentrelinePointPropertyType for location_runway_point,
    jsonb_build_object('href', runwaycentrelinepoint_huvkce.href,
    'nilreason', runwaycentrelinepoint_huvkce.nil_reason,
    'title', runwaycentrelinepoint_huvkce.simple_link_title) AS location_runway_point,
    -- composed TouchDownLiftOffPropertyType for location_aiming_point,
    jsonb_build_object('href', touchdownliftoff_gzlmmz.href,
    'nilreason', touchdownliftoff_gzlmmz.nil_reason,
    'title', touchdownliftoff_gzlmmz.simple_link_title) AS location_aiming_point,
    -- composed AirportHeliportPropertyType for location_airport_reference_point,
    jsonb_build_object('href', airportheliport_earabx.href,
    'nilreason', airportheliport_earabx.nil_reason,
    'title', airportheliport_earabx.simple_link_title) AS location_airport_reference_point,
    -- composed RoutePortionPropertyType for applicable_route_portion,
    jsonb_build_object('hjid', aixm_property_jmsjxf.hjid,
    'nilreason', aixm_property_jmsjxf.nil_reason) AS applicable_route_portion,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from route.chngovrpnttmslctp_annttn_link join aixm.aixm_property on route.chngovrpnttmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where route.changeoverpoint_t.hjid = route.chngovrpnttmslctp_annttn_link.changeoverpoint_t_hjid ) as annotation
from aixm.aixm_feature
inner join route.changeoverpoint_f on aixm.aixm_feature.hjid = route.changeoverpoint_f.hjid
inner join route.changeoverpoint_tp on aixm.aixm_feature.hjid = route.changeoverpoint_tp.timeslice_hjid
inner join route.changeoverpoint_t on route.changeoverpoint_tp.changeoverpointtimeslice_hjid = route.changeoverpoint_t.hjid
inner join aixm.aixm_timeslice on route.changeoverpoint_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed DesignatedPointPropertyType for location_fix_designated_point
left join route.chngovrpnttmslctp_lctnfxdsgntdpnt_link route_ynteem on route.changeoverpoint_t.hjid = route_ynteem.changeoverpoint_t_hjid
left join navaids_point.designatedpoint_p designatedpoint_bjxrik on route_ynteem.locationfixdesignatedpoint_hjid = designatedpoint_bjxrik.hjid
-- composed NavaidPropertyType for location_navaid_system
left join route.chngovrpnttmslctp_lctnnvdsstm_link route_ezyojg on route.changeoverpoint_t.hjid = route_ezyojg.changeoverpoint_t_hjid
left join navaids_point.navaid_p navaid_ohcpag on route_ezyojg.locationnavaidsystem_hjid = navaid_ohcpag.hjid
-- composed AIXMPointPropertyType for location_position
left join route.chngovrpnttmslctp_lctnpstn_link route_jngmys on route.changeoverpoint_t.hjid = route_jngmys.changeoverpoint_t_hjid
left join gml.aixm_point_pt_view aixm_point_pt_view_flutiv on route_jngmys.locationposition_hjid = aixm_point_pt_view_flutiv.hjid
-- composed RunwayCentrelinePointPropertyType for location_runway_point
left join route.chngovrpnttmslctp_lctnrnwpnt_link route_mgskwm on route.changeoverpoint_t.hjid = route_mgskwm.changeoverpoint_t_hjid
