--procedure.circlingarea_view

create or replace view procedure.circlingarea_view as
select distinct on (aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number)
    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_feature.hjid::text || '_' || aixm.aixm_timeslice.hjid::text) row,
    aixm.aixm_message.hjid as message_hjid,
    aixm.aixm_message.id as message_id,
    aixm.aixm_message.identifier as message_tidentifier,
    aixm.aixm_feature.hjid,
    aixm.aixm_feature.id as feature_id,
    aixm.aixm_feature.identifier,
    aixm.aixm_timeslice.id as timeslice_id,
    aixm.aixm_timeslice.hjid as timeslice_hjid,
    aixm.aixm_timeslice.interpretation,
    aixm.aixm_timeslice.sequence_number,
    aixm.aixm_timeslice.correction_number,
    aixm.aixm_timeslice.feature_lifetime_begin,
    aixm.aixm_timeslice.feature_lifetime_end,
    aixm.aixm_timeslice.valid_time_begin,
    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- composed geometry AIXMSurfacePropertyType for extent,
    aixm_surface_pt_view_mjigaj.geom as extent_geom,
    jsonb_build_object('hjid', aixm_surface_pt_view_mjigaj.hjid,
    'id', aixm_surface_pt_view_mjigaj.id,
    'horizontalaccuracy', aixm_surface_pt_view_mjigaj.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_surface_pt_view_mjigaj.horizontalaccuracy_uom,
    'horizontalaccuracy_accuracy', aixm_surface_pt_view_mjigaj.horizontalaccuracy_accuracy,
    'horizontalaccuracy_nilreason', aixm_surface_pt_view_mjigaj.horizontalaccuracy_nilreason) AS extent,
    -- composed InstrumentApproachProcedurePropertyType for approach,
    jsonb_build_object('href', instrumentapproachprocedure_itmdtl.href,
    'nilreason', instrumentapproachprocedure_itmdtl.nil_reason,
    'title', instrumentapproachprocedure_itmdtl.simple_link_title) AS approach,
    -- composed AircraftCharacteristicPropertyType for aircraft_category,
    jsonb_build_object('hjid', aixm_property_mzbxox.hjid,
    'nilreason', aixm_property_mzbxox.nil_reason) AS aircraft_category,
    -- composed ApproachConditionPropertyType for condition,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from procedure.crclngartmslctp_cndtn_link join aixm.aixm_property on procedure.crclngartmslctp_cndtn_link.condition_hjid = aixm.aixm_property.hjid where procedure.circlingarea_t.hjid = procedure.crclngartmslctp_cndtn_link.circlingarea_t_hjid ) as condition,
    -- composed ObstacleAssessmentSurfacePropertyType for design_surface,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from procedure.crclngartmslctp_dsgnsrfc_link join aixm.aixm_property on procedure.crclngartmslctp_dsgnsrfc_link.designsurface_hjid = aixm.aixm_property.hjid where procedure.circlingarea_t.hjid = procedure.crclngartmslctp_dsgnsrfc_link.circlingarea_t_hjid ) as design_surface,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from procedure.crclngartmslctp_annttn_link join aixm.aixm_property on procedure.crclngartmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where procedure.circlingarea_t.hjid = procedure.crclngartmslctp_annttn_link.circlingarea_t_hjid ) as annotation
from aixm.aixm_feature
inner join procedure.circlingarea_f on aixm.aixm_feature.hjid = procedure.circlingarea_f.hjid
inner join procedure.circlingarea_tp on aixm.aixm_feature.hjid = procedure.circlingarea_tp.timeslice_hjid
inner join procedure.circlingarea_t on procedure.circlingarea_tp.circlingareatimeslice_hjid = procedure.circlingarea_t.hjid
inner join aixm.aixm_timeslice on procedure.circlingarea_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed AIXMSurfacePropertyType for extent
left join procedure.crclngartmslctp_extnt_link procedure_qmzrhh on procedure.circlingarea_t.hjid = procedure_qmzrhh.circlingarea_t_hjid
left join gml.aixm_surface_pt_view aixm_surface_pt_view_mjigaj on procedure_qmzrhh.extent_hjid = aixm_surface_pt_view_mjigaj.hjid
-- composed InstrumentApproachProcedurePropertyType for approach
left join procedure.crclngartmslctp_apprch_link procedure_gqmjxp on procedure.circlingarea_t.hjid = procedure_gqmjxp.circlingarea_t_hjid
left join procedure.instrumentapproachprocedure_p instrumentapproachprocedure_itmdtl on procedure_gqmjxp.approach_hjid = instrumentapproachprocedure_itmdtl.hjid
-- composed AircraftCharacteristicPropertyType for aircraft_category
