left join aixm.aixm_property aixm_property_kvxfco on procedure_thqpbs.arccentre_hjid = aixm_property_kvxfco.hjid
-- composed HoldingUsePropertyType for holding
left join procedure.dprtrlgtmslctp_hldng_link procedure_jxfkep on procedure.departureleg_t.hjid = procedure_jxfkep.departureleg_t_hjid
left join aixm.aixm_property aixm_property_fdbqbn on procedure_jxfkep.holding_hjid = aixm_property_fdbqbn.hjid
-- composed DistancePropertyType for limiting_distance
left join procedure.dprtrlgtmslctp_lmtngdstnc_link procedure_npvdql on procedure.departureleg_t.hjid = procedure_npvdql.departureleg_t_hjid
left join aixm.aixm_property aixm_property_rydoyz on procedure_npvdql.limitingdistance_hjid = aixm_property_rydoyz.hjid
-- composed AnglePropertyType for limiting_angle
left join procedure.dprtrlgtmslctp_lmtngangl_link procedure_islysw on procedure.departureleg_t.hjid = procedure_islysw.departureleg_t_hjid
left join aixm.aixm_property aixm_property_ekytoc on procedure_islysw.limitingangle_hjid = aixm_property_ekytoc.hjid
-- composed StandardInstrumentDeparturePropertyType for departure
left join procedure.dprtrlgtmslctp_dprtr_link procedure_kchpke on procedure.departureleg_t.hjid = procedure_kchpke.departureleg_t_hjid
left join procedure.standardinstrumentdeparture_p standardinstrumentdeparture_vwvqke on procedure_kchpke.departure_hjid = standardinstrumentdeparture_vwvqke.hjid
