--navaids_point.designatedpoint_view

create or replace view navaids_point.designatedpoint_view as
select distinct on (aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number)
    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_feature.hjid::text || '_' || aixm.aixm_timeslice.hjid::text) row,
    aixm.aixm_message.hjid as message_hjid,
    aixm.aixm_message.id as message_id,
    aixm.aixm_message.identifier as message_tidentifier,
    aixm.aixm_feature.hjid,
    aixm.aixm_feature.id as feature_id,
    aixm.aixm_feature.identifier,
    aixm.aixm_timeslice.id as timeslice_id,
    aixm.aixm_timeslice.hjid as timeslice_hjid,
    aixm.aixm_timeslice.interpretation,
    aixm.aixm_timeslice.sequence_number,
    aixm.aixm_timeslice.correction_number,
    aixm.aixm_timeslice.feature_lifetime_begin,
    aixm.aixm_timeslice.feature_lifetime_end,
    aixm.aixm_timeslice.valid_time_begin,
    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded CodeDesignatedPointDesignatorType for getdesignatoritem,
    navaids_point.designatedpoint_t.designator::text,
    navaids_point.designatedpoint_t.designatornilreason::text,
    -- embedded CodeDesignatedPointType for gettypeitem,
    navaids_point.designatedpoint_t.type::text,
    navaids_point.designatedpoint_t.typenilreason::text,
    -- embedded TextNameType for getaixmnameitem,
    navaids_point.designatedpoint_t.name::text,
    navaids_point.designatedpoint_t.namenilreason::text,
    -- embedded CodeICAOCountryType for getcodeicaocountryitem,
    navaids_point.designatedpoint_t.codeicaocountry::text,
    navaids_point.designatedpoint_t.codeicaocountrynilreason::text,
    -- composed geometry AIXMPointPropertyType for location,
    aixm_point_pt_view_cdapsn.geom as location_geom,
    jsonb_build_object('hjid', aixm_point_pt_view_cdapsn.hjid,
    'id', aixm_point_pt_view_cdapsn.id,
    'horizontalaccuracy', aixm_point_pt_view_cdapsn.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_point_pt_view_cdapsn.horizontalaccuracy_uom,
    'horizontalaccuracy_accuracy', aixm_point_pt_view_cdapsn.horizontalaccuracy_accuracy,
    'horizontalaccuracy_nilreason', aixm_point_pt_view_cdapsn.horizontalaccuracy_nilreason) AS location,
    -- composed TouchDownLiftOffPropertyType for aiming_point,
    jsonb_build_object('href', touchdownliftoff_ithmnf.href,
    'nilreason', touchdownliftoff_ithmnf.nil_reason,
    'title', touchdownliftoff_ithmnf.simple_link_title) AS aiming_point,
    -- composed RunwayCentrelinePointPropertyType for runway_point,
    jsonb_build_object('href', runwaycentrelinepoint_brshox.href,
    'nilreason', runwaycentrelinepoint_brshox.nil_reason,
    'title', runwaycentrelinepoint_brshox.simple_link_title) AS runway_point,
    -- composed AirportHeliportPropertyType for airport_heliport,
    (select coalesce(jsonb_agg(jsonb_build_object('href', airport_heliport.airportheliport_p.href,
    'nilreason', airport_heliport.airportheliport_p.nil_reason,
    'title', airport_heliport.airportheliport_p.simple_link_title)),'[]'::jsonb) from navaids_point.dsgntdpnttmslctp_arprthlprt_link join airport_heliport.airportheliport_p on navaids_point.dsgntdpnttmslctp_arprthlprt_link.airportheliport_hjid = airport_heliport.airportheliport_p.hjid where navaids_point.designatedpoint_t.hjid = navaids_point.dsgntdpnttmslctp_arprthlprt_link.designatedpoint_t_hjid ) as airport_heliport,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from navaids_point.dsgntdpnttmslctp_annttn_link join aixm.aixm_property on navaids_point.dsgntdpnttmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where navaids_point.designatedpoint_t.hjid = navaids_point.dsgntdpnttmslctp_annttn_link.designatedpoint_t_hjid ) as annotation,
    -- composed PointReferencePropertyType for fix,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from navaids_point.dsgntdpnttmslctp_fx_link join aixm.aixm_property on navaids_point.dsgntdpnttmslctp_fx_link.fix_hjid = aixm.aixm_property.hjid where navaids_point.designatedpoint_t.hjid = navaids_point.dsgntdpnttmslctp_fx_link.designatedpoint_t_hjid ) as fix
from aixm.aixm_feature
inner join navaids_point.designatedpoint_f on aixm.aixm_feature.hjid = navaids_point.designatedpoint_f.hjid
inner join navaids_point.designatedpoint_tp on aixm.aixm_feature.hjid = navaids_point.designatedpoint_tp.timeslice_hjid
inner join navaids_point.designatedpoint_t on navaids_point.designatedpoint_tp.designatedpointtimeslice_hjid = navaids_point.designatedpoint_t.hjid
inner join aixm.aixm_timeslice on navaids_point.designatedpoint_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed AIXMPointPropertyType for location
left join navaids_point.dsgntdpnttmslctp_lctn_link navaids_point_pgpnct on navaids_point.designatedpoint_t.hjid = navaids_point_pgpnct.designatedpoint_t_hjid
left join gml.aixm_point_pt_view aixm_point_pt_view_cdapsn on navaids_point_pgpnct.location_hjid = aixm_point_pt_view_cdapsn.hjid
-- composed TouchDownLiftOffPropertyType for aiming_point
left join navaids_point.dsgntdpnttmslctp_amngpnt_link navaids_point_fryexd on navaids_point.designatedpoint_t.hjid = navaids_point_fryexd.designatedpoint_t_hjid
left join airport_heliport.touchdownliftoff_p touchdownliftoff_ithmnf on navaids_point_fryexd.aimingpoint_hjid = touchdownliftoff_ithmnf.hjid
-- composed RunwayCentrelinePointPropertyType for runway_point
left join navaids_point.dsgntdpnttmslctp_rnwpnt_link navaids_point_jdajbd on navaids_point.designatedpoint_t.hjid = navaids_point_jdajbd.designatedpoint_t_hjid
left join airport_heliport.runwaycentrelinepoint_p runwaycentrelinepoint_brshox on navaids_point_jdajbd.runwaypoint_hjid = runwaycentrelinepoint_brshox.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

