    -- composed HoldingUsePropertyType for holding,
    jsonb_build_object('hjid', aixm_property_buomab.hjid,
    'nilreason', aixm_property_buomab.nil_reason) AS holding,
    -- composed DistancePropertyType for limiting_distance,
    jsonb_build_object('hjid', aixm_property_dpshtk.hjid,
    'nilreason', aixm_property_dpshtk.nil_reason) AS limiting_distance,
    -- composed AnglePropertyType for limiting_angle,
    jsonb_build_object('hjid', aixm_property_tqjynp.hjid,
    'nilreason', aixm_property_tqjynp.nil_reason) AS limiting_angle,
    -- composed InstrumentApproachProcedurePropertyType for approach,
    jsonb_build_object('href', instrumentapproachprocedure_qrpxmo.href,
    'nilreason', instrumentapproachprocedure_qrpxmo.nil_reason,
    'title', instrumentapproachprocedure_qrpxmo.simple_link_title) AS approach,
    -- composed DesignatedPointPropertyType for final_path_alignment_point_fix_designated_point,
    jsonb_build_object('href', designatedpoint_tadnmh.href,
    'nilreason', designatedpoint_tadnmh.nil_reason,
    'title', designatedpoint_tadnmh.simple_link_title) AS final_path_alignment_point_fix_designated_point,
    -- composed NavaidPropertyType for final_path_alignment_point_navaid_system,
    jsonb_build_object('href', navaid_mhfvbb.href,
    'nilreason', navaid_mhfvbb.nil_reason,
    'title', navaid_mhfvbb.simple_link_title) AS final_path_alignment_point_navaid_system,
    -- composed RunwayCentrelinePointPropertyType for final_path_alignment_point_runway_point,
    jsonb_build_object('href', runwaycentrelinepoint_gbdmcf.href,
    'nilreason', runwaycentrelinepoint_gbdmcf.nil_reason,
    'title', runwaycentrelinepoint_gbdmcf.simple_link_title) AS final_path_alignment_point_runway_point,
    -- composed TouchDownLiftOffPropertyType for final_path_alignment_point_aiming_point,
    jsonb_build_object('href', touchdownliftoff_xnyjzj.href,
    'nilreason', touchdownliftoff_xnyjzj.nil_reason,
    'title', touchdownliftoff_xnyjzj.simple_link_title) AS final_path_alignment_point_aiming_point,
    -- composed AirportHeliportPropertyType for final_path_alignment_point_airport_reference_point,
    jsonb_build_object('href', airportheliport_ulcamf.href,
    'nilreason', airportheliport_ulcamf.nil_reason,
    'title', airportheliport_ulcamf.simple_link_title) AS final_path_alignment_point_airport_reference_point,
    -- composed TerminalSegmentPointPropertyType for visual_descent_point,
    jsonb_build_object('hjid', aixm_property_qoqdop.hjid,
    'nilreason', aixm_property_qoqdop.nil_reason) AS visual_descent_point,
    -- composed FinalApproachSegmentDataPropertyType for fas_data,
    jsonb_build_object('hjid', aixm_property_eagcwc.hjid,
    'nilreason', aixm_property_eagcwc.nil_reason) AS fas_data,
    -- composed ObstacleAssessmentSurfacePropertyType for design_surface,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from procedure.fnllgtmslctp_dsgnsrfc_link join aixm.aixm_property on procedure.fnllgtmslctp_dsgnsrfc_link.designsurface_hjid = aixm.aixm_property.hjid where procedure.finalleg_t.hjid = procedure.fnllgtmslctp_dsgnsrfc_link.finalleg_t_hjid ) as design_surface,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from procedure.fnllgtmslctp_annttn_link join aixm.aixm_property on procedure.fnllgtmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where procedure.finalleg_t.hjid = procedure.fnllgtmslctp_annttn_link.finalleg_t_hjid ) as annotation,
    -- composed AircraftCharacteristicPropertyType for aircraft_capability,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from procedure.fnllgtmslctp_arcrftcpblt_link join aixm.aixm_property on procedure.fnllgtmslctp_arcrftcpblt_link.aircraftcapability_hjid = aixm.aixm_property.hjid where procedure.finalleg_t.hjid = procedure.fnllgtmslctp_arcrftcpblt_link.finalleg_t_hjid ) as aircraft_capability,
    -- composed CourseGroupPropertyType for segment_course,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from procedure.fnllgtmslctp_sgmntcrs_link join aixm.aixm_property on procedure.fnllgtmslctp_sgmntcrs_link.segmentcourse_hjid = aixm.aixm_property.hjid where procedure.finalleg_t.hjid = procedure.fnllgtmslctp_sgmntcrs_link.finalleg_t_hjid ) as segment_course,
    -- composed SegmentLegAltitudeConditionPropertyType for altitude_condition,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from procedure.fnllgtmslctp_alttdcndtn_link join aixm.aixm_property on procedure.fnllgtmslctp_alttdcndtn_link.altitudecondition_hjid = aixm.aixm_property.hjid where procedure.finalleg_t.hjid = procedure.fnllgtmslctp_alttdcndtn_link.finalleg_t_hjid ) as altitude_condition,
    -- composed ApproachConditionPropertyType for condition,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from procedure.fnllgtmslctp_cndtn_link join aixm.aixm_property on procedure.fnllgtmslctp_cndtn_link.condition_hjid = aixm.aixm_property.hjid where procedure.finalleg_t.hjid = procedure.fnllgtmslctp_cndtn_link.finalleg_t_hjid ) as condition
from aixm.aixm_feature
inner join procedure.finalleg_f on aixm.aixm_feature.hjid = procedure.finalleg_f.hjid
inner join procedure.finalleg_tp on aixm.aixm_feature.hjid = procedure.finalleg_tp.timeslice_hjid
inner join procedure.finalleg_t on procedure.finalleg_tp.finallegtimeslice_hjid = procedure.finalleg_t.hjid
inner join aixm.aixm_timeslice on procedure.finalleg_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed TerminalSegmentPointPropertyType for start_point
left join procedure.fnllgtmslctp_strtpnt_link procedure_bbadaq on procedure.finalleg_t.hjid = procedure_bbadaq.finalleg_t_hjid
left join aixm.aixm_property aixm_property_oaucbf on procedure_bbadaq.startpoint_hjid = aixm_property_oaucbf.hjid
-- composed TerminalSegmentPointPropertyType for end_point
left join procedure.fnllgtmslctp_endpnt_link procedure_jzvdup on procedure.finalleg_t.hjid = procedure_jzvdup.finalleg_t_hjid
left join aixm.aixm_property aixm_property_ptxmpx on procedure_jzvdup.endpoint_hjid = aixm_property_ptxmpx.hjid
-- composed AIXMCurvePropertyType for trajectory
left join procedure.fnllgtmslctp_trjctr_link procedure_knaegc on procedure.finalleg_t.hjid = procedure_knaegc.finalleg_t_hjid
left join gml.aixm_curve_pt_view aixm_curve_pt_view_wmzbxu on procedure_knaegc.trajectory_hjid = aixm_curve_pt_view_wmzbxu.hjid
-- composed TerminalSegmentPointPropertyType for arc_centre
left join procedure.fnllgtmslctp_arccntr_link procedure_hakbvf on procedure.finalleg_t.hjid = procedure_hakbvf.finalleg_t_hjid
left join aixm.aixm_property aixm_property_hlvljb on procedure_hakbvf.arccentre_hjid = aixm_property_hlvljb.hjid
-- composed HoldingUsePropertyType for holding
left join procedure.fnllgtmslctp_hldng_link procedure_mmlyib on procedure.finalleg_t.hjid = procedure_mmlyib.finalleg_t_hjid
left join aixm.aixm_property aixm_property_buomab on procedure_mmlyib.holding_hjid = aixm_property_buomab.hjid
-- composed DistancePropertyType for limiting_distance
left join procedure.fnllgtmslctp_lmtngdstnc_link procedure_keywox on procedure.finalleg_t.hjid = procedure_keywox.finalleg_t_hjid
left join aixm.aixm_property aixm_property_dpshtk on procedure_keywox.limitingdistance_hjid = aixm_property_dpshtk.hjid
-- composed AnglePropertyType for limiting_angle
left join procedure.fnllgtmslctp_lmtngangl_link procedure_jmnski on procedure.finalleg_t.hjid = procedure_jmnski.finalleg_t_hjid
left join aixm.aixm_property aixm_property_tqjynp on procedure_jmnski.limitingangle_hjid = aixm_property_tqjynp.hjid
-- composed InstrumentApproachProcedurePropertyType for approach
left join procedure.fnllgtmslctp_apprch_link procedure_zygziv on procedure.finalleg_t.hjid = procedure_zygziv.finalleg_t_hjid
left join procedure.instrumentapproachprocedure_p instrumentapproachprocedure_qrpxmo on procedure_zygziv.approach_hjid = instrumentapproachprocedure_qrpxmo.hjid
-- composed DesignatedPointPropertyType for final_path_alignment_point_fix_designated_point
left join procedure.fnllgtmslctp_fnlpthalgnmntpntfxdsgntdpnt_link procedure_noidaz on procedure.finalleg_t.hjid = procedure_noidaz.finalleg_t_hjid
left join navaids_point.designatedpoint_p designatedpoint_tadnmh on procedure_noidaz.finalpathalignmentpointfixdesignatedpoint_hjid = designatedpoint_tadnmh.hjid
-- composed NavaidPropertyType for final_path_alignment_point_navaid_system
left join procedure.fnllgtmslctp_fnlpthalgnmntpntnvdsstm_link procedure_gpcuoj on procedure.finalleg_t.hjid = procedure_gpcuoj.finalleg_t_hjid
left join navaids_point.navaid_p navaid_mhfvbb on procedure_gpcuoj.finalpathalignmentpointnavaidsystem_hjid = navaid_mhfvbb.hjid
-- composed AIXMPointPropertyType for final_path_alignment_point_position
left join procedure.fnllgtmslctp_fnlpthalgnmntpntpstn_link procedure_hftwfx on procedure.finalleg_t.hjid = procedure_hftwfx.finalleg_t_hjid
left join gml.aixm_point_pt_view aixm_point_pt_view_kaovxg on procedure_hftwfx.finalpathalignmentpointposition_hjid = aixm_point_pt_view_kaovxg.hjid
-- composed RunwayCentrelinePointPropertyType for final_path_alignment_point_runway_point
left join procedure.fnllgtmslctp_fnlpthalgnmntpntrnwpnt_link procedure_nljywl on procedure.finalleg_t.hjid = procedure_nljywl.finalleg_t_hjid
left join airport_heliport.runwaycentrelinepoint_p runwaycentrelinepoint_gbdmcf on procedure_nljywl.finalpathalignmentpointrunwaypoint_hjid = runwaycentrelinepoint_gbdmcf.hjid
-- composed TouchDownLiftOffPropertyType for final_path_alignment_point_aiming_point
left join procedure.fnllgtmslctp_fnlpthalgnmntpntamngpnt_link procedure_uvqqyx on procedure.finalleg_t.hjid = procedure_uvqqyx.finalleg_t_hjid
left join airport_heliport.touchdownliftoff_p touchdownliftoff_xnyjzj on procedure_uvqqyx.finalpathalignmentpointaimingpoint_hjid = touchdownliftoff_xnyjzj.hjid
-- composed AirportHeliportPropertyType for final_path_alignment_point_airport_reference_point
left join procedure.fnllgtmslctp_fnlpthalgnmntpntarprtrfrncpnt_link procedure_dmookd on procedure.finalleg_t.hjid = procedure_dmookd.finalleg_t_hjid
left join airport_heliport.airportheliport_p airportheliport_ulcamf on procedure_dmookd.finalpathalignmentpointairportreferencepoint_hjid = airportheliport_ulcamf.hjid
-- composed TerminalSegmentPointPropertyType for visual_descent_point
left join procedure.fnllgtmslctp_vsldscntpnt_link procedure_lzzbce on procedure.finalleg_t.hjid = procedure_lzzbce.finalleg_t_hjid
left join aixm.aixm_property aixm_property_qoqdop on procedure_lzzbce.visualdescentpoint_hjid = aixm_property_qoqdop.hjid
-- composed FinalApproachSegmentDataPropertyType for fas_data
left join procedure.fnllgtmslctp_fasdt_link procedure_ilncpx on procedure.finalleg_t.hjid = procedure_ilncpx.finalleg_t_hjid
left join aixm.aixm_property aixm_property_eagcwc on procedure_ilncpx.fasdata_hjid = aixm_property_eagcwc.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

--service.firefightingservice_view

create or replace view service.firefightingservice_view as
select distinct on (aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number)
    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_feature.hjid::text || '_' || aixm.aixm_timeslice.hjid::text) row,
    aixm.aixm_message.hjid as message_hjid,
    aixm.aixm_message.id as message_id,
    aixm.aixm_message.identifier as message_tidentifier,
    aixm.aixm_feature.hjid,
    aixm.aixm_feature.id as feature_id,
    aixm.aixm_feature.identifier,
    aixm.aixm_timeslice.id as timeslice_id,
    aixm.aixm_timeslice.hjid as timeslice_hjid,
    aixm.aixm_timeslice.interpretation,
    aixm.aixm_timeslice.sequence_number,
    aixm.aixm_timeslice.correction_number,
    aixm.aixm_timeslice.feature_lifetime_begin,
    aixm.aixm_timeslice.feature_lifetime_end,
    aixm.aixm_timeslice.valid_time_begin,
    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded CodeFlightDestinationType for getflightoperationsitem,
    service.firefightingservice_t.flightoperations::text,
    service.firefightingservice_t.flightoperationsnilreason::text,
    -- embedded CodeFacilityRankingType for getrankitem,
    service.firefightingservice_t.rank::text,
    service.firefightingservice_t.ranknilreason::text,
    -- embedded CodeYesNoType for getcomplianticaoitem,
    service.firefightingservice_t.complianticao::text,
    service.firefightingservice_t.complianticaonilreason::text,
    -- embedded TextNameType for getaixmnameitem,
    service.firefightingservice_t.name::text,
    service.firefightingservice_t.namenilreason::text,
    -- embedded CodeFireFightingType for getcategoryitem,
    service.firefightingservice_t.category::text,
    service.firefightingservice_t.categorynilreason::text,
    -- embedded CodeAviationStandardsType for getstandarditem,
    service.firefightingservice_t.standard::text,
    service.firefightingservice_t.standardnilreason::text,
    -- composed geometry AIXMElevatedPointPropertyType for location,
    aixm_elevated_point_pt_view_qpteva.geom as location_geom,
    jsonb_build_object('hjid', aixm_elevated_point_pt_view_qpteva.hjid,
    'id', aixm_elevated_point_pt_view_qpteva.id,
    'horizontalaccuracy', aixm_elevated_point_pt_view_qpteva.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_elevated_point_pt_view_qpteva.horizontalaccuracy_uom,
    'horizontalaccuracy_accuracy', aixm_elevated_point_pt_view_qpteva.horizontalaccuracy_accuracy,
    'horizontalaccuracy_nilreason', aixm_elevated_point_pt_view_qpteva.horizontalaccuracy_nilreason,
    'geoidundulation', aixm_elevated_point_pt_view_qpteva.geoidundulation,
    'geoidundulation_accuracy', aixm_elevated_point_pt_view_qpteva.geoidundulation_accuracy,
    'geoidundulation_nilreason', aixm_elevated_point_pt_view_qpteva.geoidundulation_nilreason,
    'elevation', aixm_elevated_point_pt_view_qpteva.elevation,
    'elevation_uom', aixm_elevated_point_pt_view_qpteva.elevation_uom,
    'elevation_accuracy', aixm_elevated_point_pt_view_qpteva.elevation_accuracy,
    'elevation_nilreason', aixm_elevated_point_pt_view_qpteva.elevation_nilreason) AS location,
    -- composed UnitPropertyType for service_provider,
    jsonb_build_object('href', unit_dxdnak.href,
    'nilreason', unit_dxdnak.nil_reason,
    'title', unit_dxdnak.simple_link_title) AS service_provider,
    -- composed RadioCommunicationChannelPropertyType for radio_communication,
    (select coalesce(jsonb_agg(jsonb_build_object('href', service.radiocommunicationchannel_p.href,
    'nilreason', service.radiocommunicationchannel_p.nil_reason,
    'title', service.radiocommunicationchannel_p.simple_link_title)),'[]'::jsonb) from service.frfghtngsrvctmslctp_rdcmmnctn_link join service.radiocommunicationchannel_p on service.frfghtngsrvctmslctp_rdcmmnctn_link.radiocommunication_hjid = service.radiocommunicationchannel_p.hjid where service.firefightingservice_t.hjid = service.frfghtngsrvctmslctp_rdcmmnctn_link.firefightingservice_t_hjid ) as radio_communication,
    -- composed ContactInformationPropertyType for ground_communication,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from service.frfghtngsrvctmslctp_grndcmmnctn_link join aixm.aixm_property on service.frfghtngsrvctmslctp_grndcmmnctn_link.groundcommunication_hjid = aixm.aixm_property.hjid where service.firefightingservice_t.hjid = service.frfghtngsrvctmslctp_grndcmmnctn_link.firefightingservice_t_hjid ) as ground_communication,
    -- composed ServiceOperationalStatusPropertyType for availability,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from service.frfghtngsrvctmslctp_avlblt_link join aixm.aixm_property on service.frfghtngsrvctmslctp_avlblt_link.availability_hjid = aixm.aixm_property.hjid where service.firefightingservice_t.hjid = service.frfghtngsrvctmslctp_avlblt_link.firefightingservice_t_hjid ) as availability,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from service.frfghtngsrvctmslctp_annttn_link join aixm.aixm_property on service.frfghtngsrvctmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where service.firefightingservice_t.hjid = service.frfghtngsrvctmslctp_annttn_link.firefightingservice_t_hjid ) as annotation,
    -- composed AirportHeliportPropertyType for airport_heliport,
    (select coalesce(jsonb_agg(jsonb_build_object('href', airport_heliport.airportheliport_p.href,
    'nilreason', airport_heliport.airportheliport_p.nil_reason,
    'title', airport_heliport.airportheliport_p.simple_link_title)),'[]'::jsonb) from service.frfghtngsrvctmslctp_arprthlprt_link join airport_heliport.airportheliport_p on service.frfghtngsrvctmslctp_arprthlprt_link.airportheliport_hjid = airport_heliport.airportheliport_p.hjid where service.firefightingservice_t.hjid = service.frfghtngsrvctmslctp_arprthlprt_link.firefightingservice_t_hjid ) as airport_heliport
from aixm.aixm_feature
inner join service.firefightingservice_f on aixm.aixm_feature.hjid = service.firefightingservice_f.hjid
inner join service.firefightingservice_tp on aixm.aixm_feature.hjid = service.firefightingservice_tp.timeslice_hjid
inner join service.firefightingservice_t on service.firefightingservice_tp.firefightingservicetimeslice_hjid = service.firefightingservice_t.hjid
inner join aixm.aixm_timeslice on service.firefightingservice_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed AIXMElevatedPointPropertyType for location
left join service.frfghtngsrvctmslctp_lctn_link service_wkdubf on service.firefightingservice_t.hjid = service_wkdubf.firefightingservice_t_hjid
left join gml.aixm_elevated_point_pt_view aixm_elevated_point_pt_view_qpteva on service_wkdubf.location_hjid = aixm_elevated_point_pt_view_qpteva.hjid
-- composed UnitPropertyType for service_provider
left join service.frfghtngsrvctmslctp_srvcprvdr_link service_bikyxy on service.firefightingservice_t.hjid = service_bikyxy.firefightingservice_t_hjid
left join organisation.unit_p unit_dxdnak on service_bikyxy.serviceprovider_hjid = unit_dxdnak.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

--route.flightrestriction_view

