    -- composed TaxiwayPropertyType for connected_taxiway,
    (select coalesce(jsonb_agg(jsonb_build_object('href', airport_heliport.taxiway_p.href,
    'nilreason', airport_heliport.taxiway_p.nil_reason,
    'title', airport_heliport.taxiway_p.simple_link_title)),'[]'::jsonb) from airport_heliport.gdnclntmslctp_cnnctdtxw_link join airport_heliport.taxiway_p on airport_heliport.gdnclntmslctp_cnnctdtxw_link.connectedtaxiway_hjid = airport_heliport.taxiway_p.hjid where airport_heliport.guidanceline_t.hjid = airport_heliport.gdnclntmslctp_cnnctdtxw_link.guidanceline_t_hjid ) as connected_taxiway,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from airport_heliport.gdnclntmslctp_annttn_link join aixm.aixm_property on airport_heliport.gdnclntmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where airport_heliport.guidanceline_t.hjid = airport_heliport.gdnclntmslctp_annttn_link.guidanceline_t_hjid ) as annotation,
    -- composed GuidanceLineDirectionPropertyType for availability,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from airport_heliport.gdnclntmslctp_avlblt_link join aixm.aixm_property on airport_heliport.gdnclntmslctp_avlblt_link.availability_hjid = aixm.aixm_property.hjid where airport_heliport.guidanceline_t.hjid = airport_heliport.gdnclntmslctp_avlblt_link.guidanceline_t_hjid ) as availability
from aixm.aixm_feature
inner join airport_heliport.guidanceline_f on aixm.aixm_feature.hjid = airport_heliport.guidanceline_f.hjid
inner join airport_heliport.guidanceline_tp on aixm.aixm_feature.hjid = airport_heliport.guidanceline_tp.timeslice_hjid
inner join airport_heliport.guidanceline_t on airport_heliport.guidanceline_tp.guidancelinetimeslice_hjid = airport_heliport.guidanceline_t.hjid
inner join aixm.aixm_timeslice on airport_heliport.guidanceline_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed AIXMElevatedCurvePropertyType for extent
left join airport_heliport.gdnclntmslctp_extnt_link airport_heliport_hirguf on airport_heliport.guidanceline_t.hjid = airport_heliport_hirguf.guidanceline_t_hjid
left join gml.aixm_elevated_curve_pt_view aixm_elevated_curve_pt_view_ntcoan on airport_heliport_hirguf.extent_hjid = aixm_elevated_curve_pt_view_ntcoan.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

--shared.holdingassessment_view

