    shared.holdingassessment_t.upperlimituom::text,
    shared.holdingassessment_t.upperlimitaccuracy::text,
    shared.holdingassessment_t.upperlimitnilreason::text,
    -- embedded ValDistanceVerticalType for getlowerlimititem,
