    shared.holdingassessment_t.leglengthtowarduom::text,
    shared.holdingassessment_t.leglengthtowardaccuracy::text,
    shared.holdingassessment_t.leglengthtowardnilreason::text,
    -- embedded ValDistanceType for getleglengthawayitem,
