    shared.holdingassessment_t.leglengthawayuom::text,
    shared.holdingassessment_t.leglengthawayaccuracy::text,
    shared.holdingassessment_t.leglengthawaynilreason::text,
    -- composed SegmentPointPropertyType for holding_point,
    jsonb_build_object('hjid', aixm_property_yjynrc.hjid,
    'nilreason', aixm_property_yjynrc.nil_reason) AS holding_point,
    -- composed UnplannedHoldingPropertyType for unplanned_holding,
    jsonb_build_object('href', unplannedholding_dgaozk.href,
    'nilreason', unplannedholding_dgaozk.nil_reason,
    'title', unplannedholding_dgaozk.simple_link_title) AS unplanned_holding,
    -- composed HoldingPatternPropertyType for assessed_holding_pattern,
    jsonb_build_object('href', holdingpattern_qfwtfn.href,
    'nilreason', holdingpattern_qfwtfn.nil_reason,
    'title', holdingpattern_qfwtfn.simple_link_title) AS assessed_holding_pattern,
    -- composed ObstacleAssessmentSurfacePropertyType for obstacle_assessment,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from shared.hldngassssmnttmslctp_obstclassssmnt_link join aixm.aixm_property on shared.hldngassssmnttmslctp_obstclassssmnt_link.obstacleassessment_hjid = aixm.aixm_property.hjid where shared.holdingassessment_t.hjid = shared.hldngassssmnttmslctp_obstclassssmnt_link.holdingassessment_t_hjid ) as obstacle_assessment,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from shared.hldngassssmnttmslctp_annttn_link join aixm.aixm_property on shared.hldngassssmnttmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where shared.holdingassessment_t.hjid = shared.hldngassssmnttmslctp_annttn_link.holdingassessment_t_hjid ) as annotation
from aixm.aixm_feature
inner join shared.holdingassessment_f on aixm.aixm_feature.hjid = shared.holdingassessment_f.hjid
inner join shared.holdingassessment_tp on aixm.aixm_feature.hjid = shared.holdingassessment_tp.timeslice_hjid
inner join shared.holdingassessment_t on shared.holdingassessment_tp.holdingassessmenttimeslice_hjid = shared.holdingassessment_t.hjid
inner join aixm.aixm_timeslice on shared.holdingassessment_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed SegmentPointPropertyType for holding_point
left join shared.hldngassssmnttmslctp_hldngpnt_link shared_fkoycm on shared.holdingassessment_t.hjid = shared_fkoycm.holdingassessment_t_hjid
left join aixm.aixm_property aixm_property_yjynrc on shared_fkoycm.holdingpoint_hjid = aixm_property_yjynrc.hjid
-- composed UnplannedHoldingPropertyType for unplanned_holding
left join shared.hldngassssmnttmslctp_unplnndhldng_link shared_pdgzvp on shared.holdingassessment_t.hjid = shared_pdgzvp.holdingassessment_t_hjid
left join holding.unplannedholding_p unplannedholding_dgaozk on shared_pdgzvp.unplannedholding_hjid = unplannedholding_dgaozk.hjid
-- composed HoldingPatternPropertyType for assessed_holding_pattern
left join shared.hldngassssmnttmslctp_assssdhldngpttrn_link shared_xkjuvn on shared.holdingassessment_t.hjid = shared_xkjuvn.holdingassessment_t_hjid
left join holding.holdingpattern_p holdingpattern_qfwtfn on shared_xkjuvn.assessedholdingpattern_hjid = holdingpattern_qfwtfn.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

