    'horizontalaccuracy_uom', aixm_curve_pt_view_jyhwrp.horizontalaccuracy_uom,
    'horizontalaccuracy_accuracy', aixm_curve_pt_view_jyhwrp.horizontalaccuracy_accuracy,
    'horizontalaccuracy_nilreason', aixm_curve_pt_view_jyhwrp.horizontalaccuracy_nilreason) AS extent,
