    jsonb_build_object('hjid', aixm_property_todyga.hjid,
    'nilreason', aixm_property_todyga.nil_reason) AS outbound_leg_span_end_distance,
    -- composed SegmentPointPropertyType for holding_point,
    jsonb_build_object('hjid', aixm_property_vxzkrj.hjid,
    'nilreason', aixm_property_vxzkrj.nil_reason) AS holding_point,
    -- composed CourseGroupPropertyType for outbound_course,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from holding.hldngpttrntmslctp_otbndcrs_link join aixm.aixm_property on holding.hldngpttrntmslctp_otbndcrs_link.outboundcourse_hjid = aixm.aixm_property.hjid where holding.holdingpattern_t.hjid = holding.hldngpttrntmslctp_otbndcrs_link.holdingpattern_t_hjid ) as outbound_course,
    -- composed CourseGroupPropertyType for inbound_course,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from holding.hldngpttrntmslctp_inbndcrs_link join aixm.aixm_property on holding.hldngpttrntmslctp_inbndcrs_link.inboundcourse_hjid = aixm.aixm_property.hjid where holding.holdingpattern_t.hjid = holding.hldngpttrntmslctp_inbndcrs_link.holdingpattern_t_hjid ) as inbound_course,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from holding.hldngpttrntmslctp_annttn_link join aixm.aixm_property on holding.hldngpttrntmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where holding.holdingpattern_t.hjid = holding.hldngpttrntmslctp_annttn_link.holdingpattern_t_hjid ) as annotation,
    -- composed DesignStandardPropertyType for design_criteria,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from holding.hldngpttrntmslctp_dsgncrtr_link join aixm.aixm_property on holding.hldngpttrntmslctp_dsgncrtr_link.designcriteria_hjid = aixm.aixm_property.hjid where holding.holdingpattern_t.hjid = holding.hldngpttrntmslctp_dsgncrtr_link.holdingpattern_t_hjid ) as design_criteria
from aixm.aixm_feature
inner join holding.holdingpattern_f on aixm.aixm_feature.hjid = holding.holdingpattern_f.hjid
inner join holding.holdingpattern_tp on aixm.aixm_feature.hjid = holding.holdingpattern_tp.timeslice_hjid
inner join holding.holdingpattern_t on holding.holdingpattern_tp.holdingpatterntimeslice_hjid = holding.holdingpattern_t.hjid
inner join aixm.aixm_timeslice on holding.holdingpattern_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed SegmentPointPropertyType for outbound_leg_span_end_point
left join holding.hldngpttrntmslctp_otbndlgspnendpnt_link holding_scupzb on holding.holdingpattern_t.hjid = holding_scupzb.holdingpattern_t_hjid
left join aixm.aixm_property aixm_property_wljvvb on holding_scupzb.outboundlegspanendpoint_hjid = aixm_property_wljvvb.hjid
-- composed HoldingPatternDurationPropertyType for outbound_leg_span_end_time
