left join aixm.aixm_property aixm_property_ifvcij on holding_tbfgrj.outboundlegspanendtime_hjid = aixm_property_ifvcij.hjid
-- composed HoldingPatternDistancePropertyType for outbound_leg_span_end_distance
left join holding.hldngpttrntmslctp_otbndlgspnenddstnc_link holding_lnvcil on holding.holdingpattern_t.hjid = holding_lnvcil.holdingpattern_t_hjid
left join aixm.aixm_property aixm_property_todyga on holding_lnvcil.outboundlegspanenddistance_hjid = aixm_property_todyga.hjid
-- composed SegmentPointPropertyType for holding_point
left join holding.hldngpttrntmslctp_hldngpnt_link holding_grxgtd on holding.holdingpattern_t.hjid = holding_grxgtd.holdingpattern_t_hjid
left join aixm.aixm_property aixm_property_vxzkrj on holding_grxgtd.holdingpoint_hjid = aixm_property_vxzkrj.hjid
-- composed AIXMCurvePropertyType for extent
left join holding.hldngpttrntmslctp_extnt_link holding_blsucn on holding.holdingpattern_t.hjid = holding_blsucn.holdingpattern_t_hjid
left join gml.aixm_curve_pt_view aixm_curve_pt_view_jyhwrp on holding_blsucn.extent_hjid = aixm_curve_pt_view_jyhwrp.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

