    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from service.infrmtnsrvctmslctp_clntrt_link join aixm.aixm_property on service.infrmtnsrvctmslctp_clntrt_link.clientroute_hjid = aixm.aixm_property.hjid where service.informationservice_t.hjid = service.infrmtnsrvctmslctp_clntrt_link.informationservice_t_hjid ) as client_route,
