    -- composed WeatherSourcePropertyType for aixm_data_source,
    (select coalesce(jsonb_agg(jsonb_build_object('href', airport_heliport.weathersource_p.href,
    'nilreason', airport_heliport.weathersource_p.nil_reason,
    'title', airport_heliport.weathersource_p.simple_link_title)),'[]'::jsonb) from service.infrmtnsrvctmslctp_dtsrc_link join airport_heliport.weathersource_p on service.infrmtnsrvctmslctp_dtsrc_link.datasource_hjid = airport_heliport.weathersource_p.hjid where service.informationservice_t.hjid = service.infrmtnsrvctmslctp_dtsrc_link.informationservice_t_hjid ) as aixm_data_source
from aixm.aixm_feature
inner join service.informationservice_f on aixm.aixm_feature.hjid = service.informationservice_f.hjid
inner join service.informationservice_tp on aixm.aixm_feature.hjid = service.informationservice_tp.timeslice_hjid
inner join service.informationservice_t on service.informationservice_tp.informationservicetimeslice_hjid = service.informationservice_t.hjid
inner join aixm.aixm_timeslice on service.informationservice_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed AIXMElevatedPointPropertyType for location
left join service.infrmtnsrvctmslctp_lctn_link service_yilfei on service.informationservice_t.hjid = service_yilfei.informationservice_t_hjid
left join gml.aixm_elevated_point_pt_view aixm_elevated_point_pt_view_yigsst on service_yilfei.location_hjid = aixm_elevated_point_pt_view_yigsst.hjid
-- composed UnitPropertyType for service_provider
left join service.infrmtnsrvctmslctp_srvcprvdr_link service_deolby on service.informationservice_t.hjid = service_deolby.informationservice_t_hjid
left join organisation.unit_p unit_czikel on service_deolby.serviceprovider_hjid = unit_czikel.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

--procedure.initialleg_view

create or replace view procedure.initialleg_view as
select distinct on (aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number)
    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_feature.hjid::text || '_' || aixm.aixm_timeslice.hjid::text) row,
    aixm.aixm_message.hjid as message_hjid,
    aixm.aixm_message.id as message_id,
    aixm.aixm_message.identifier as message_tidentifier,
    aixm.aixm_feature.hjid,
    aixm.aixm_feature.id as feature_id,
    aixm.aixm_feature.identifier,
    aixm.aixm_timeslice.id as timeslice_id,
