    jsonb_build_object('hjid', aixm_property_tvgczl.hjid,
    'nilreason', aixm_property_tvgczl.nil_reason) AS limiting_angle,
    -- composed InstrumentApproachProcedurePropertyType for approach,
    jsonb_build_object('href', instrumentapproachprocedure_nvonne.href,
    'nilreason', instrumentapproachprocedure_nvonne.nil_reason,
    'title', instrumentapproachprocedure_nvonne.simple_link_title) AS approach,
    -- composed ObstacleAssessmentSurfacePropertyType for design_surface,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from procedure.intllgtmslctp_dsgnsrfc_link join aixm.aixm_property on procedure.intllgtmslctp_dsgnsrfc_link.designsurface_hjid = aixm.aixm_property.hjid where procedure.initialleg_t.hjid = procedure.intllgtmslctp_dsgnsrfc_link.initialleg_t_hjid ) as design_surface,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from procedure.intllgtmslctp_annttn_link join aixm.aixm_property on procedure.intllgtmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where procedure.initialleg_t.hjid = procedure.intllgtmslctp_annttn_link.initialleg_t_hjid ) as annotation,
    -- composed AircraftCharacteristicPropertyType for aircraft_capability,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from procedure.intllgtmslctp_arcrftcpblt_link join aixm.aixm_property on procedure.intllgtmslctp_arcrftcpblt_link.aircraftcapability_hjid = aixm.aixm_property.hjid where procedure.initialleg_t.hjid = procedure.intllgtmslctp_arcrftcpblt_link.initialleg_t_hjid ) as aircraft_capability,
    -- composed CourseGroupPropertyType for segment_course,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from procedure.intllgtmslctp_sgmntcrs_link join aixm.aixm_property on procedure.intllgtmslctp_sgmntcrs_link.segmentcourse_hjid = aixm.aixm_property.hjid where procedure.initialleg_t.hjid = procedure.intllgtmslctp_sgmntcrs_link.initialleg_t_hjid ) as segment_course,
    -- composed SegmentLegAltitudeConditionPropertyType for altitude_condition,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from procedure.intllgtmslctp_alttdcndtn_link join aixm.aixm_property on procedure.intllgtmslctp_alttdcndtn_link.altitudecondition_hjid = aixm.aixm_property.hjid where procedure.initialleg_t.hjid = procedure.intllgtmslctp_alttdcndtn_link.initialleg_t_hjid ) as altitude_condition
