inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed TerminalSegmentPointPropertyType for start_point
left join procedure.intllgtmslctp_strtpnt_link procedure_gyzqzf on procedure.initialleg_t.hjid = procedure_gyzqzf.initialleg_t_hjid
left join aixm.aixm_property aixm_property_ycidcb on procedure_gyzqzf.startpoint_hjid = aixm_property_ycidcb.hjid
-- composed TerminalSegmentPointPropertyType for end_point
left join procedure.intllgtmslctp_endpnt_link procedure_gywgoo on procedure.initialleg_t.hjid = procedure_gywgoo.initialleg_t_hjid
left join aixm.aixm_property aixm_property_yzsmwm on procedure_gywgoo.endpoint_hjid = aixm_property_yzsmwm.hjid
-- composed AIXMCurvePropertyType for trajectory
left join procedure.intllgtmslctp_trjctr_link procedure_rguocb on procedure.initialleg_t.hjid = procedure_rguocb.initialleg_t_hjid
left join gml.aixm_curve_pt_view aixm_curve_pt_view_uxeaip on procedure_rguocb.trajectory_hjid = aixm_curve_pt_view_uxeaip.hjid
