left join aixm.aixm_property aixm_property_gtlmun on procedure_lsekiw.arccentre_hjid = aixm_property_gtlmun.hjid
-- composed HoldingUsePropertyType for holding
left join procedure.intllgtmslctp_hldng_link procedure_iczkyl on procedure.initialleg_t.hjid = procedure_iczkyl.initialleg_t_hjid
left join aixm.aixm_property aixm_property_wknmvo on procedure_iczkyl.holding_hjid = aixm_property_wknmvo.hjid
-- composed DistancePropertyType for limiting_distance
left join procedure.intllgtmslctp_lmtngdstnc_link procedure_onrilh on procedure.initialleg_t.hjid = procedure_onrilh.initialleg_t_hjid
left join aixm.aixm_property aixm_property_dvvdnw on procedure_onrilh.limitingdistance_hjid = aixm_property_dvvdnw.hjid
-- composed AnglePropertyType for limiting_angle
left join procedure.intllgtmslctp_lmtngangl_link procedure_axbvpn on procedure.initialleg_t.hjid = procedure_axbvpn.initialleg_t_hjid
left join aixm.aixm_property aixm_property_tvgczl on procedure_axbvpn.limitingangle_hjid = aixm_property_tvgczl.hjid
-- composed InstrumentApproachProcedurePropertyType for approach
left join procedure.intllgtmslctp_apprch_link procedure_qxqxtr on procedure.initialleg_t.hjid = procedure_qxqxtr.initialleg_t_hjid
left join procedure.instrumentapproachprocedure_p instrumentapproachprocedure_nvonne on procedure_qxqxtr.approach_hjid = instrumentapproachprocedure_nvonne.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

