left join aixm.aixm_property aixm_property_vwavpi on procedure_ghmiar.limitingdistance_hjid = aixm_property_vwavpi.hjid
-- composed AnglePropertyType for limiting_angle
left join procedure.intrmdtlgtmslctp_lmtngangl_link procedure_cgfxhw on procedure.intermediateleg_t.hjid = procedure_cgfxhw.intermediateleg_t_hjid
left join aixm.aixm_property aixm_property_vxhshj on procedure_cgfxhw.limitingangle_hjid = aixm_property_vxhshj.hjid
-- composed InstrumentApproachProcedurePropertyType for approach
left join procedure.intrmdtlgtmslctp_apprch_link procedure_uqrksi on procedure.intermediateleg_t.hjid = procedure_uqrksi.intermediateleg_t_hjid
left join procedure.instrumentapproachprocedure_p instrumentapproachprocedure_oekqbi on procedure_uqrksi.approach_hjid = instrumentapproachprocedure_oekqbi.hjid
