    navaids_point.navaid_t.integritylevel::text,
    navaids_point.navaid_t.integritylevelnilreason::text,
    -- embedded CodeICAOCountryType for getcodeicaocountryitem,
    navaids_point.navaid_t.codeicaocountry::text,
    navaids_point.navaid_t.codeicaocountrynilreason::text,
    -- composed geometry AIXMElevatedPointPropertyType for location,
    aixm_elevated_point_pt_view_zqmjwj.geom as location_geom,
    jsonb_build_object('hjid', aixm_elevated_point_pt_view_zqmjwj.hjid,
    'id', aixm_elevated_point_pt_view_zqmjwj.id,
    'horizontalaccuracy', aixm_elevated_point_pt_view_zqmjwj.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_elevated_point_pt_view_zqmjwj.horizontalaccuracy_uom,
    'horizontalaccuracy_accuracy', aixm_elevated_point_pt_view_zqmjwj.horizontalaccuracy_accuracy,
    'horizontalaccuracy_nilreason', aixm_elevated_point_pt_view_zqmjwj.horizontalaccuracy_nilreason,
    'geoidundulation', aixm_elevated_point_pt_view_zqmjwj.geoidundulation,
    'geoidundulation_accuracy', aixm_elevated_point_pt_view_zqmjwj.geoidundulation_accuracy,
    'geoidundulation_nilreason', aixm_elevated_point_pt_view_zqmjwj.geoidundulation_nilreason,
    'elevation', aixm_elevated_point_pt_view_zqmjwj.elevation,
    'elevation_uom', aixm_elevated_point_pt_view_zqmjwj.elevation_uom,
    'elevation_accuracy', aixm_elevated_point_pt_view_zqmjwj.elevation_accuracy,
    'elevation_nilreason', aixm_elevated_point_pt_view_zqmjwj.elevation_nilreason) AS location,
    -- composed TouchDownLiftOffPropertyType for touch_down_lift_off,
    (select coalesce(jsonb_agg(jsonb_build_object('href', airport_heliport.touchdownliftoff_p.href,
    'nilreason', airport_heliport.touchdownliftoff_p.nil_reason,
    'title', airport_heliport.touchdownliftoff_p.simple_link_title)),'[]'::jsonb) from navaids_point.nvdtmslctp_tchdwnlftoff_link join airport_heliport.touchdownliftoff_p on navaids_point.nvdtmslctp_tchdwnlftoff_link.touchdownliftoff_hjid = airport_heliport.touchdownliftoff_p.hjid where navaids_point.navaid_t.hjid = navaids_point.nvdtmslctp_tchdwnlftoff_link.navaid_t_hjid ) as touch_down_lift_off,
    -- composed NavaidComponentPropertyType for navaid_equipment,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
