left join service.pssngrsrvctmslctp_lctn_link service_acvhdg on service.passengerservice_t.hjid = service_acvhdg.passengerservice_t_hjid
left join gml.aixm_elevated_point_pt_view aixm_elevated_point_pt_view_gmadiy on service_acvhdg.location_hjid = aixm_elevated_point_pt_view_gmadiy.hjid
