    -- composed NavaidEquipmentPropertyType for equipment_navaid_equipment,
    jsonb_build_object('hjid', aixm_property_mylagb.hjid,
    'nilreason', aixm_property_mylagb.nil_reason) AS equipment_navaid_equipment,
    -- composed CircleSectorPropertyType for sector,
