    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from shared.rdfrqncartmslctp_sctr_link join aixm.aixm_property on shared.rdfrqncartmslctp_sctr_link.sector_hjid = aixm.aixm_property.hjid where shared.radiofrequencyarea_t.hjid = shared.rdfrqncartmslctp_sctr_link.radiofrequencyarea_t_hjid ) as sector,
    -- composed geometry AIXMSurfacePropertyType for extent,
    (select st_union(gml.aixm_surface_pt_view.GEOM) as extent_geom from shared.rdfrqncartmslctp_extnt_link join gml.aixm_surface_pt_view on shared.rdfrqncartmslctp_extnt_link.extent_hjid = gml.aixm_surface_pt_view.hjid where shared.radiofrequencyarea_t.hjid = shared.rdfrqncartmslctp_extnt_link.radiofrequencyarea_t_hjid ) as extent_geom,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', gml.aixm_surface_pt_view.hjid,
    'id', gml.aixm_surface_pt_view.id,
    'horizontalaccuracy', gml.aixm_surface_pt_view.horizontalaccuracy,
