    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from route.rtsgmnttmslctp_annttn_link join aixm.aixm_property on route.rtsgmnttmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where route.routesegment_t.hjid = route.rtsgmnttmslctp_annttn_link.routesegment_t_hjid ) as annotation,
