    -- composed AirspaceLayerClassPropertyType for airspace_class,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from route.rtsgmnttmslctp_arspcclss_link join aixm.aixm_property on route.rtsgmnttmslctp_arspcclss_link.airspaceclass_hjid = aixm.aixm_property.hjid where route.routesegment_t.hjid = route.rtsgmnttmslctp_arspcclss_link.routesegment_t_hjid ) as airspace_class
from aixm.aixm_feature
inner join route.routesegment_f on aixm.aixm_feature.hjid = route.routesegment_f.hjid
inner join route.routesegment_tp on aixm.aixm_feature.hjid = route.routesegment_tp.timeslice_hjid
inner join route.routesegment_t on route.routesegment_tp.routesegmenttimeslice_hjid = route.routesegment_t.hjid
inner join aixm.aixm_timeslice on route.routesegment_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed EnRouteSegmentPointPropertyType for start
left join route.rtsgmnttmslctp_strt_link route_ihguji on route.routesegment_t.hjid = route_ihguji.routesegment_t_hjid
left join aixm.aixm_property aixm_property_evossr on route_ihguji.start_hjid = aixm_property_evossr.hjid
-- composed RoutePropertyType for route_formed
left join route.rtsgmnttmslctp_rtfrmd_link route_rsmifu on route.routesegment_t.hjid = route_rsmifu.routesegment_t_hjid
left join route.route_p route_ygvpdz on route_rsmifu.routeformed_hjid = route_ygvpdz.hjid
-- composed ObstacleAssessmentSurfacePropertyType for evaluation_area
left join route.rtsgmnttmslctp_evltnar_link route_cydhrt on route.routesegment_t.hjid = route_cydhrt.routesegment_t_hjid
left join aixm.aixm_property aixm_property_gzghow on route_cydhrt.evaluationarea_hjid = aixm_property_gzghow.hjid
-- composed AIXMCurvePropertyType for curve_extent
left join route.rtsgmnttmslctp_crvextnt_link route_dgwyui on route.routesegment_t.hjid = route_dgwyui.routesegment_t_hjid
left join gml.aixm_curve_pt_view aixm_curve_pt_view_cjgagg on route_dgwyui.curveextent_hjid = aixm_curve_pt_view_cjgagg.hjid
-- composed EnRouteSegmentPointPropertyType for end
left join route.rtsgmnttmslctp_end__link route_vtvyzj on route.routesegment_t.hjid = route_vtvyzj.routesegment_t_hjid
left join aixm.aixm_property aixm_property_tmqxoa on route_vtvyzj.end__hjid = aixm_property_tmqxoa.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

--route.route_view

