    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded CodeRouteDesignatorPrefixType for getdesignatorprefixitem,
    route.route_t.designatorprefix::text,
