    -- embedded CodeRouteDesignatorLetterType for getdesignatorsecondletteritem,
    route.route_t.designatorsecondletter::text,
    route.route_t.designatorsecondletternilreason::text,
    -- embedded NoNumberType for getdesignatornumberitem,
    route.route_t.designatornumber::text,
    route.route_t.designatornumbernilreason::text,
    -- embedded CodeUpperAlphaType for getmultipleidentifieritem,
    route.route_t.multipleidentifier::text,
    route.route_t.multipleidentifiernilreason::text,
    -- embedded TextDesignatorType for getlocationdesignatoritem,
    route.route_t.locationdesignator::text,
    route.route_t.locationdesignatornilreason::text,
    -- embedded TextNameType for getaixmnameitem,
    route.route_t.name::text,
    route.route_t.namenilreason::text,
    -- embedded CodeRouteType for gettypeitem,
    route.route_t.type::text,
    route.route_t.typenilreason::text,
    -- embedded CodeFlightRuleType for getflightruleitem,
    route.route_t.flightrule::text,
    route.route_t.flightrulenilreason::text,
    -- embedded CodeRouteOriginType for getinternationaluseitem,
    route.route_t.internationaluse::text,
    route.route_t.internationalusenilreason::text,
    -- embedded CodeMilitaryStatusType for getmilitaryuseitem,
    route.route_t.militaryuse::text,
    route.route_t.militaryusenilreason::text,
    -- embedded CodeMilitaryTrainingType for getmilitarytrainingtypeitem,
    route.route_t.militarytrainingtype::text,
    route.route_t.militarytrainingtypenilreason::text,
    -- composed OrganisationAuthorityPropertyType for user_organisation,
    jsonb_build_object('href', organisationauthority_sfwdzb.href,
    'nilreason', organisationauthority_sfwdzb.nil_reason,
    'title', organisationauthority_sfwdzb.simple_link_title) AS user_organisation,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from route.rttmslctp_annttn_link join aixm.aixm_property on route.rttmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where route.route_t.hjid = route.rttmslctp_annttn_link.route_t_hjid ) as annotation,
    -- composed DesignStandardPropertyType for design_criteria,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from route.rttmslctp_dsgncrtr_link join aixm.aixm_property on route.rttmslctp_dsgncrtr_link.designcriteria_hjid = aixm.aixm_property.hjid where route.route_t.hjid = route.rttmslctp_dsgncrtr_link.route_t_hjid ) as design_criteria,
    -- composed RouteAvailabilityPropertyType for availability,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from route.rttmslctp_avlblt_link join aixm.aixm_property on route.rttmslctp_avlblt_link.availability_hjid = aixm.aixm_property.hjid where route.route_t.hjid = route.rttmslctp_avlblt_link.route_t_hjid ) as availability,
    -- composed AircraftCharacteristicPropertyType for aircraft_capability,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from route.rttmslctp_arcrftcpblt_link join aixm.aixm_property on route.rttmslctp_arcrftcpblt_link.aircraftcapability_hjid = aixm.aixm_property.hjid where route.route_t.hjid = route.rttmslctp_arcrftcpblt_link.route_t_hjid ) as aircraft_capability
from aixm.aixm_feature
inner join route.route_f on aixm.aixm_feature.hjid = route.route_f.hjid
inner join route.route_tp on aixm.aixm_feature.hjid = route.route_tp.timeslice_hjid
inner join route.route_t on route.route_tp.routetimeslice_hjid = route.route_t.hjid
inner join aixm.aixm_timeslice on route.route_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed OrganisationAuthorityPropertyType for user_organisation
left join route.rttmslctp_usrorgnstn_link route_eexmrd on route.route_t.hjid = route_eexmrd.route_t_hjid
left join organisation.organisationauthority_p organisationauthority_sfwdzb on route_eexmrd.userorganisation_hjid = organisationauthority_sfwdzb.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

