    'elevation_nilreason', aixm_elevated_surface_pt_view_uqinyy.elevation_nilreason) AS extent,
    -- composed AirportHeliportPropertyType for associated_airport_heliport,
    jsonb_build_object('href', airportheliport_xbsssz.href,
    'nilreason', airportheliport_xbsssz.nil_reason,
    'title', airportheliport_xbsssz.simple_link_title) AS associated_airport_heliport,
    -- composed SeaplaneRampSitePropertyType for ramp_site,
    (select coalesce(jsonb_agg(jsonb_build_object('href', airport_heliport.seaplanerampsite_p.href,
