    (select coalesce(jsonb_agg(jsonb_build_object('href', airport_heliport.floatingdocksite_p.href,
    'nilreason', airport_heliport.floatingdocksite_p.nil_reason,
    'title', airport_heliport.floatingdocksite_p.simple_link_title)),'[]'::jsonb) from airport_heliport.splnlndngartmslctp_dckst_link join airport_heliport.floatingdocksite_p on airport_heliport.splnlndngartmslctp_dckst_link.docksite_hjid = airport_heliport.floatingdocksite_p.hjid where airport_heliport.seaplanelandingarea_t.hjid = airport_heliport.splnlndngartmslctp_dckst_link.seaplanelandingarea_t_hjid ) as dock_site,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
