    -- composed ManoeuvringAreaAvailabilityPropertyType for availability,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from airport_heliport.splnlndngartmslctp_avlblt_link join aixm.aixm_property on airport_heliport.splnlndngartmslctp_avlblt_link.availability_hjid = aixm.aixm_property.hjid where airport_heliport.seaplanelandingarea_t.hjid = airport_heliport.splnlndngartmslctp_avlblt_link.seaplanelandingarea_t_hjid ) as availability,
    -- composed GangwayPropertyType for assigned_gangway,
    (select coalesce(jsonb_agg(jsonb_build_object('href', airport_heliport.gangway_p.href,
    'nilreason', airport_heliport.gangway_p.nil_reason,
    'title', airport_heliport.gangway_p.simple_link_title)),'[]'::jsonb) from airport_heliport.splnlndngartmslctp_assgndgngw_link join airport_heliport.gangway_p on airport_heliport.splnlndngartmslctp_assgndgngw_link.assignedgangway_hjid = airport_heliport.gangway_p.hjid where airport_heliport.seaplanelandingarea_t.hjid = airport_heliport.splnlndngartmslctp_assgndgngw_link.seaplanelandingarea_t_hjid ) as assigned_gangway
from aixm.aixm_feature
inner join airport_heliport.seaplanelandingarea_f on aixm.aixm_feature.hjid = airport_heliport.seaplanelandingarea_f.hjid
inner join airport_heliport.seaplanelandingarea_tp on aixm.aixm_feature.hjid = airport_heliport.seaplanelandingarea_tp.timeslice_hjid
inner join airport_heliport.seaplanelandingarea_t on airport_heliport.seaplanelandingarea_tp.seaplanelandingareatimeslice_hjid = airport_heliport.seaplanelandingarea_t.hjid
inner join aixm.aixm_timeslice on airport_heliport.seaplanelandingarea_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed AIXMElevatedSurfacePropertyType for extent
left join airport_heliport.splnlndngartmslctp_extnt_link airport_heliport_hcgmcb on airport_heliport.seaplanelandingarea_t.hjid = airport_heliport_hcgmcb.seaplanelandingarea_t_hjid
left join gml.aixm_elevated_surface_pt_view aixm_elevated_surface_pt_view_uqinyy on airport_heliport_hcgmcb.extent_hjid = aixm_elevated_surface_pt_view_uqinyy.hjid
-- composed AirportHeliportPropertyType for associated_airport_heliport
left join airport_heliport.splnlndngartmslctp_assctdarprthlprt_link airport_heliport_cxhopa on airport_heliport.seaplanelandingarea_t.hjid = airport_heliport_cxhopa.seaplanelandingarea_t_hjid
left join airport_heliport.airportheliport_p airportheliport_xbsssz on airport_heliport_cxhopa.associatedairportheliport_hjid = airportheliport_xbsssz.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

