    'title', service.radiocommunicationchannel_p.simple_link_title)),'[]'::jsonb) from service.srchrscsrvctmslctp_rdcmmnctn_link join service.radiocommunicationchannel_p on service.srchrscsrvctmslctp_rdcmmnctn_link.radiocommunication_hjid = service.radiocommunicationchannel_p.hjid where service.searchrescueservice_t.hjid = service.srchrscsrvctmslctp_rdcmmnctn_link.searchrescueservice_t_hjid ) as radio_communication,
