    -- composed RoutePortionPropertyType for client_route,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from service.srchrscsrvctmslctp_clntrt_link join aixm.aixm_property on service.srchrscsrvctmslctp_clntrt_link.clientroute_hjid = aixm.aixm_property.hjid where service.searchrescueservice_t.hjid = service.srchrscsrvctmslctp_clntrt_link.searchrescueservice_t_hjid ) as client_route,
    -- composed RouteSegmentPropertyType for client_segment,
