    airport_heliport.touchdownliftofflightsystem_t.positionnilreason::text,
    -- composed TouchDownLiftOffPropertyType for lighted_touch_down_lift_off,
    jsonb_build_object('href', touchdownliftoff_vpssvr.href,
    'nilreason', touchdownliftoff_vpssvr.nil_reason,
    'title', touchdownliftoff_vpssvr.simple_link_title) AS lighted_touch_down_lift_off,
    -- composed LightElementPropertyType for element,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from airport_heliport.tchdwnlftofflghtsstmtmslctp_elmnt_link join aixm.aixm_property on airport_heliport.tchdwnlftofflghtsstmtmslctp_elmnt_link.element_hjid = aixm.aixm_property.hjid where airport_heliport.touchdownliftofflightsystem_t.hjid = airport_heliport.tchdwnlftofflghtsstmtmslctp_elmnt_link.touchdownliftofflightsystem_t_hjid ) as element,
    -- composed GroundLightingAvailabilityPropertyType for availability,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from airport_heliport.tchdwnlftofflghtsstmtmslctp_avlblt_link join aixm.aixm_property on airport_heliport.tchdwnlftofflghtsstmtmslctp_avlblt_link.availability_hjid = aixm.aixm_property.hjid where airport_heliport.touchdownliftofflightsystem_t.hjid = airport_heliport.tchdwnlftofflghtsstmtmslctp_avlblt_link.touchdownliftofflightsystem_t_hjid ) as availability,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from airport_heliport.tchdwnlftofflghtsstmtmslctp_annttn_link join aixm.aixm_property on airport_heliport.tchdwnlftofflghtsstmtmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where airport_heliport.touchdownliftofflightsystem_t.hjid = airport_heliport.tchdwnlftofflghtsstmtmslctp_annttn_link.touchdownliftofflightsystem_t_hjid ) as annotation
from aixm.aixm_feature
inner join airport_heliport.touchdownliftofflightsystem_f on aixm.aixm_feature.hjid = airport_heliport.touchdownliftofflightsystem_f.hjid
inner join airport_heliport.touchdownliftofflightsystem_tp on aixm.aixm_feature.hjid = airport_heliport.touchdownliftofflightsystem_tp.timeslice_hjid
inner join airport_heliport.touchdownliftofflightsystem_t on airport_heliport.touchdownliftofflightsystem_tp.touchdownliftofflightsystemtimeslice_hjid = airport_heliport.touchdownliftofflightsystem_t.hjid
inner join aixm.aixm_timeslice on airport_heliport.touchdownliftofflightsystem_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed TouchDownLiftOffPropertyType for lighted_touch_down_lift_off
left join airport_heliport.tchdwnlftofflghtsstmtmslctp_lghtdtchdwnlftoff_link airport_heliport_wyzarq on airport_heliport.touchdownliftofflightsystem_t.hjid = airport_heliport_wyzarq.touchdownliftofflightsystem_t_hjid
left join airport_heliport.touchdownliftoff_p touchdownliftoff_vpssvr on airport_heliport_wyzarq.lightedtouchdownliftoff_hjid = touchdownliftoff_vpssvr.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

