left join organisation.unttmslctp_pstn_link organisation_lvdxtl on organisation.unit_t.hjid = organisation_lvdxtl.unit_t_hjid
left join gml.aixm_elevated_point_pt_view aixm_elevated_point_pt_view_pyywmo on organisation_lvdxtl.position_hjid = aixm_elevated_point_pt_view_pyywmo.hjid
