left join organisation.organisationauthority_p organisationauthority_ezsvjf on organisation_fiduup.ownerorganisation_hjid = organisationauthority_ezsvjf.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

