    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_feature.hjid::text || '_' || aixm.aixm_timeslice.hjid::text) row,
    aixm.aixm_message.hjid as message_hjid,
    aixm.aixm_message.id as message_id,
    aixm.aixm_message.identifier as message_tidentifier,
    aixm.aixm_feature.hjid,
    aixm.aixm_feature.id as feature_id,
    aixm.aixm_feature.identifier,
    aixm.aixm_timeslice.id as timeslice_id,
    aixm.aixm_timeslice.hjid as timeslice_hjid,
    aixm.aixm_timeslice.interpretation,
    aixm.aixm_timeslice.sequence_number,
    aixm.aixm_timeslice.correction_number,
    aixm.aixm_timeslice.feature_lifetime_begin,
    aixm.aixm_timeslice.feature_lifetime_end,
    aixm.aixm_timeslice.valid_time_begin,
    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded TextDesignatorType for getdesignatoritem,
    airport_heliport.weathersource_t.designator::text,
    airport_heliport.weathersource_t.designatornilreason::text,
    -- embedded CodeWeatherSourceType for getsensortypeitem,
    airport_heliport.weathersource_t.sensortype::text,
    airport_heliport.weathersource_t.sensortypenilreason::text,
    -- composed geometry AIXMElevatedPointPropertyType for position,
    aixm_elevated_point_pt_view_egqtuq.geom as position_geom,
    jsonb_build_object('hjid', aixm_elevated_point_pt_view_egqtuq.hjid,
    'id', aixm_elevated_point_pt_view_egqtuq.id,
    'horizontalaccuracy', aixm_elevated_point_pt_view_egqtuq.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_elevated_point_pt_view_egqtuq.horizontalaccuracy_uom,
    'horizontalaccuracy_accuracy', aixm_elevated_point_pt_view_egqtuq.horizontalaccuracy_accuracy,
    'horizontalaccuracy_nilreason', aixm_elevated_point_pt_view_egqtuq.horizontalaccuracy_nilreason,
    'geoidundulation', aixm_elevated_point_pt_view_egqtuq.geoidundulation,
    'geoidundulation_accuracy', aixm_elevated_point_pt_view_egqtuq.geoidundulation_accuracy,
    'geoidundulation_nilreason', aixm_elevated_point_pt_view_egqtuq.geoidundulation_nilreason,
    'elevation', aixm_elevated_point_pt_view_egqtuq.elevation,
    'elevation_uom', aixm_elevated_point_pt_view_egqtuq.elevation_uom,
    'elevation_accuracy', aixm_elevated_point_pt_view_egqtuq.elevation_accuracy,
    'elevation_nilreason', aixm_elevated_point_pt_view_egqtuq.elevation_nilreason) AS position,
    -- composed WeatherSourceAvailabilityPropertyType for availability,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from airport_heliport.wthrsrctmslctp_avlblt_link join aixm.aixm_property on airport_heliport.wthrsrctmslctp_avlblt_link.availability_hjid = aixm.aixm_property.hjid where airport_heliport.weathersource_t.hjid = airport_heliport.wthrsrctmslctp_avlblt_link.weathersource_t_hjid ) as availability,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from airport_heliport.wthrsrctmslctp_annttn_link join aixm.aixm_property on airport_heliport.wthrsrctmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where airport_heliport.weathersource_t.hjid = airport_heliport.wthrsrctmslctp_annttn_link.weathersource_t_hjid ) as annotation
from aixm.aixm_feature
inner join airport_heliport.weathersource_f on aixm.aixm_feature.hjid = airport_heliport.weathersource_f.hjid
inner join airport_heliport.weathersource_tp on aixm.aixm_feature.hjid = airport_heliport.weathersource_tp.timeslice_hjid
inner join airport_heliport.weathersource_t on airport_heliport.weathersource_tp.weathersourcetimeslice_hjid = airport_heliport.weathersource_t.hjid
inner join aixm.aixm_timeslice on airport_heliport.weathersource_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed AIXMElevatedPointPropertyType for position
left join airport_heliport.wthrsrctmslctp_pstn_link airport_heliport_mhfsoy on airport_heliport.weathersource_t.hjid = airport_heliport_mhfsoy.weathersource_t_hjid
left join gml.aixm_elevated_point_pt_view aixm_elevated_point_pt_view_egqtuq on airport_heliport_mhfsoy.position_hjid = aixm_elevated_point_pt_view_egqtuq.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

