    airport_heliport.workarea_t.plannedoperationalnilreason::text,
    -- composed geometry AIXMElevatedSurfacePropertyType for extent,
    aixm_elevated_surface_pt_view_vphahl.geom as extent_geom,
    jsonb_build_object('hjid', aixm_elevated_surface_pt_view_vphahl.hjid,
