    'horizontalaccuracy_uom', aixm_elevated_surface_pt_view_vphahl.horizontalaccuracy_uom,
    'horizontalaccuracy_accuracy', aixm_elevated_surface_pt_view_vphahl.horizontalaccuracy_accuracy,
    'horizontalaccuracy_nilreason', aixm_elevated_surface_pt_view_vphahl.horizontalaccuracy_nilreason,
    'geoidundulation', aixm_elevated_surface_pt_view_vphahl.geoidundulation,
    'geoidundulation_accuracy', aixm_elevated_surface_pt_view_vphahl.geoidundulation_accuracy,
    'geoidundulation_nilreason', aixm_elevated_surface_pt_view_vphahl.geoidundulation_nilreason,
    'elevation', aixm_elevated_surface_pt_view_vphahl.elevation,
    'elevation_uom', aixm_elevated_surface_pt_view_vphahl.elevation_uom,
    'elevation_accuracy', aixm_elevated_surface_pt_view_vphahl.elevation_accuracy,
    'elevation_nilreason', aixm_elevated_surface_pt_view_vphahl.elevation_nilreason) AS extent,
    -- composed AirportHeliportPropertyType for associated_airport_heliport,
    jsonb_build_object('href', airportheliport_vmbczs.href,
    'nilreason', airportheliport_vmbczs.nil_reason,
    'title', airportheliport_vmbczs.simple_link_title) AS associated_airport_heliport,
    -- composed WorkareaActivityPropertyType for activation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from airport_heliport.wrkartmslctp_actvtn_link join aixm.aixm_property on airport_heliport.wrkartmslctp_actvtn_link.activation_hjid = aixm.aixm_property.hjid where airport_heliport.workarea_t.hjid = airport_heliport.wrkartmslctp_actvtn_link.workarea_t_hjid ) as activation,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from airport_heliport.wrkartmslctp_annttn_link join aixm.aixm_property on airport_heliport.wrkartmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where airport_heliport.workarea_t.hjid = airport_heliport.wrkartmslctp_annttn_link.workarea_t_hjid ) as annotation
from aixm.aixm_feature
inner join airport_heliport.workarea_f on aixm.aixm_feature.hjid = airport_heliport.workarea_f.hjid
inner join airport_heliport.workarea_tp on aixm.aixm_feature.hjid = airport_heliport.workarea_tp.timeslice_hjid
inner join airport_heliport.workarea_t on airport_heliport.workarea_tp.workareatimeslice_hjid = airport_heliport.workarea_t.hjid
inner join aixm.aixm_timeslice on airport_heliport.workarea_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed AirportHeliportPropertyType for associated_airport_heliport
left join airport_heliport.wrkartmslctp_assctdarprthlprt_link airport_heliport_zkgdaq on airport_heliport.workarea_t.hjid = airport_heliport_zkgdaq.workarea_t_hjid
left join airport_heliport.airportheliport_p airportheliport_vmbczs on airport_heliport_zkgdaq.associatedairportheliport_hjid = airportheliport_vmbczs.hjid
-- composed AIXMElevatedSurfacePropertyType for extent
left join airport_heliport.wrkartmslctp_extnt_link airport_heliport_xykism on airport_heliport.workarea_t.hjid = airport_heliport_xykism.workarea_t_hjid
left join gml.aixm_elevated_surface_pt_view aixm_elevated_surface_pt_view_vphahl on airport_heliport_xykism.extent_hjid = aixm_elevated_surface_pt_view_vphahl.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

