    aerial_refuelling.aerialrefuellinganchor_o.leglengthuom::text,
    aerial_refuelling.aerialrefuellinganchor_o.leglengthaccuracy::text,
    aerial_refuelling.aerialrefuellinganchor_o.leglengthnilreason::text,
    -- embedded ValDistanceVerticalType for getrefuellingbaselevelitem,
    aerial_refuelling.aerialrefuellinganchor_o.refuellingbaselevel::text,
    aerial_refuelling.aerialrefuellinganchor_o.refuellingbaseleveluom::text,
    aerial_refuelling.aerialrefuellinganchor_o.refuellingbaselevelaccuracy::text,
    aerial_refuelling.aerialrefuellinganchor_o.refuellingbaselevelnilreason::text,
    -- composed geometry AIXMSurfacePropertyType for extent,
    aixm_surface_pt_view_ajholm.geom as extent_geom,
    jsonb_build_object('hjid', aixm_surface_pt_view_ajholm.hjid,
    'id', aixm_surface_pt_view_ajholm.id,
    'horizontalaccuracy', aixm_surface_pt_view_ajholm.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_surface_pt_view_ajholm.horizontalaccuracy_uom,
    'horizontalaccuracy_accuracy', aixm_surface_pt_view_ajholm.horizontalaccuracy_accuracy,
    'horizontalaccuracy_nilreason', aixm_surface_pt_view_ajholm.horizontalaccuracy_nilreason ) AS extent,
    -- composed CourseGroupPropertyType for outbound_course,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from aerial_refuelling.arlrfllnganchrtp_otbndcrs_link join aixm.aixm_property on aerial_refuelling.arlrfllnganchrtp_otbndcrs_link.outboundcourse_hjid = aixm.aixm_property.hjid where aerial_refuelling.aerialrefuellinganchor_o.hjid = aerial_refuelling.arlrfllnganchrtp_otbndcrs_link.aerialrefuellinganchor_o_hjid ) as outbound_course,
    -- composed CourseGroupPropertyType for inbound_course,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from aerial_refuelling.arlrfllnganchrtp_inbndcrs_link join aixm.aixm_property on aerial_refuelling.arlrfllnganchrtp_inbndcrs_link.inboundcourse_hjid = aixm.aixm_property.hjid where aerial_refuelling.aerialrefuellinganchor_o.hjid = aerial_refuelling.arlrfllnganchrtp_inbndcrs_link.aerialrefuellinganchor_o_hjid ) as inbound_course,
    -- composed AirspaceLayerPropertyType for vertical_extent,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from aerial_refuelling.arlrfllnganchrtp_vrtclextnt_link join aixm.aixm_property on aerial_refuelling.arlrfllnganchrtp_vrtclextnt_link.verticalextent_hjid = aixm.aixm_property.hjid where aerial_refuelling.aerialrefuellinganchor_o.hjid = aerial_refuelling.arlrfllnganchrtp_vrtclextnt_link.aerialrefuellinganchor_o_hjid ) as vertical_extent,
    -- composed AerialRefuellingPointPropertyType for point,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from aerial_refuelling.arlrfllnganchrtp_pnt_link join aixm.aixm_property on aerial_refuelling.arlrfllnganchrtp_pnt_link.point_hjid = aixm.aixm_property.hjid where aerial_refuelling.aerialrefuellinganchor_o.hjid = aerial_refuelling.arlrfllnganchrtp_pnt_link.aerialrefuellinganchor_o_hjid ) as point,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from aerial_refuelling.arlrfllnganchrtp_annttn_link join aixm.aixm_property on aerial_refuelling.arlrfllnganchrtp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where aerial_refuelling.aerialrefuellinganchor_o.hjid = aerial_refuelling.arlrfllnganchrtp_annttn_link.aerialrefuellinganchor_o_hjid ) as annotation
from aerial_refuelling.aerialrefuellinganchor_p 
inner join aixm.aixm_property on aerial_refuelling.aerialrefuellinganchor_p.hjid = aixm.aixm_property.hjid
inner join aerial_refuelling.aerialrefuellinganchor_o on aerial_refuelling.aerialrefuellinganchor_p.aerialrefuellinganchor_hjid = aerial_refuelling.aerialrefuellinganchor_o.hjid
inner join aixm.aixm_object on aerial_refuelling.aerialrefuellinganchor_o.hjid = aixm.aixm_object.hjid
-- composed AIXMSurfacePropertyType for extent
left join aerial_refuelling.arlrfllnganchrtp_extnt_link aerial_refuelling_fkqwsl on aerial_refuelling.aerialrefuellinganchor_o.hjid = aerial_refuelling_fkqwsl.aerialrefuellinganchor_o_hjid
left join gml.aixm_surface_pt_view aixm_surface_pt_view_ajholm on aerial_refuelling_fkqwsl.extent_hjid = aixm_surface_pt_view_ajholm.hjid
;;

--aerial_refuelling.aerialrefuellingpoint_view

