    -- embedded CodeAerialRefuellingPointType for getusagetypeitem,
    aerial_refuelling.aerialrefuellingpoint_o.usagetype::text,
    aerial_refuelling.aerialrefuellingpoint_o.usagetypenilreason::text,
    -- composed geometry AIXMPointPropertyType for point_choice_position,
    aixm_point_pt_view_icmvdg.geom as point_choice_position_geom,
    jsonb_build_object('hjid', aixm_point_pt_view_icmvdg.hjid,
    'id', aixm_point_pt_view_icmvdg.id,
    'horizontalaccuracy', aixm_point_pt_view_icmvdg.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_point_pt_view_icmvdg.horizontalaccuracy_uom,
    'horizontalaccuracy_accuracy', aixm_point_pt_view_icmvdg.horizontalaccuracy_accuracy,
    'horizontalaccuracy_nilreason', aixm_point_pt_view_icmvdg.horizontalaccuracy_nilreason ) AS point_choice_position,
    -- composed DesignatedPointPropertyType for point_choice_fix_designated_point,
    jsonb_build_object('href', designatedpoint_fwwofb.href,
    'nilreason', designatedpoint_fwwofb.nil_reason,
    'title', designatedpoint_fwwofb.simple_link_title) AS point_choice_fix_designated_point,
    -- composed NavaidPropertyType for point_choice_navaid_system,
    jsonb_build_object('href', navaid_ncobnu.href,
    'nilreason', navaid_ncobnu.nil_reason,
    'title', navaid_ncobnu.simple_link_title) AS point_choice_navaid_system,
    -- composed RunwayCentrelinePointPropertyType for point_choice_runway_point,
    jsonb_build_object('href', runwaycentrelinepoint_vulydw.href,
    'nilreason', runwaycentrelinepoint_vulydw.nil_reason,
    'title', runwaycentrelinepoint_vulydw.simple_link_title) AS point_choice_runway_point,
    -- composed TouchDownLiftOffPropertyType for point_choice_aiming_point,
    jsonb_build_object('href', touchdownliftoff_rorzyz.href,
    'nilreason', touchdownliftoff_rorzyz.nil_reason,
    'title', touchdownliftoff_rorzyz.simple_link_title) AS point_choice_aiming_point,
    -- composed AirportHeliportPropertyType for point_choice_airport_reference_point,
    jsonb_build_object('href', airportheliport_brqnnq.href,
    'nilreason', airportheliport_brqnnq.nil_reason,
    'title', airportheliport_brqnnq.simple_link_title) AS point_choice_airport_reference_point,
    -- composed RadioFrequencyAreaPropertyType for extended_service_volume,
    jsonb_build_object('href', radiofrequencyarea_kblvmc.href,
    'nilreason', radiofrequencyarea_kblvmc.nil_reason,
    'title', radiofrequencyarea_kblvmc.simple_link_title) AS extended_service_volume,
