    procedure.circlingrestriction_p.hjid as hjid,
    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_object.id::text) row,
    aixm.aixm_property.nil_reason::text AS nilreason,
    aixm.aixm_object.id,
    aixm.aixm_object.hjid as object_hjid,
    -- composed geometry AIXMSurfacePropertyType for restriction_area,
    aixm_surface_pt_view_rcctaa.geom as restriction_area_geom,
    jsonb_build_object('hjid', aixm_surface_pt_view_rcctaa.hjid,
    'id', aixm_surface_pt_view_rcctaa.id,
    'horizontalaccuracy', aixm_surface_pt_view_rcctaa.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_surface_pt_view_rcctaa.horizontalaccuracy_uom,
    'horizontalaccuracy_accuracy', aixm_surface_pt_view_rcctaa.horizontalaccuracy_accuracy,
    'horizontalaccuracy_nilreason', aixm_surface_pt_view_rcctaa.horizontalaccuracy_nilreason ) AS restriction_area,
    -- composed CircleSectorPropertyType for sector_description,
    jsonb_build_object('hjid', aixm_property_mpamfl.hjid,
    'nilreason', aixm_property_mpamfl.nil_reason) AS sector_description,
    -- composed TimesheetPropertyType for time_interval,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from procedure.crclngrstrctntp_tmintrvl_link join aixm.aixm_property on procedure.crclngrstrctntp_tmintrvl_link.timeinterval_hjid = aixm.aixm_property.hjid where procedure.circlingrestriction_o.hjid = procedure.crclngrstrctntp_tmintrvl_link.circlingrestriction_o_hjid ) as time_interval,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from procedure.crclngrstrctntp_annttn_link join aixm.aixm_property on procedure.crclngrstrctntp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where procedure.circlingrestriction_o.hjid = procedure.crclngrstrctntp_annttn_link.circlingrestriction_o_hjid ) as annotation,
    -- composed geometry OrganisationAuthorityPropertyType for special_date_authority,
    (select coalesce(jsonb_agg(jsonb_build_object('href', organisation.organisationauthority_p.href,
    'nilreason', organisation.organisationauthority_p.nil_reason,
    'title', organisation.organisationauthority_p.simple_link_title)),'[]'::jsonb) from procedure.crclngrstrctntp_spcldtathrt_link join organisation.organisationauthority_p on procedure.crclngrstrctntp_spcldtathrt_link.specialdateauthority_hjid = organisation.organisationauthority_p.hjid where procedure.circlingrestriction_o.hjid = procedure.crclngrstrctntp_spcldtathrt_link.circlingrestriction_o_hjid ) as special_date_authority
from procedure.circlingrestriction_p 
inner join aixm.aixm_property on procedure.circlingrestriction_p.hjid = aixm.aixm_property.hjid
inner join procedure.circlingrestriction_o on procedure.circlingrestriction_p.circlingrestriction_hjid = procedure.circlingrestriction_o.hjid
inner join aixm.aixm_object on procedure.circlingrestriction_o.hjid = aixm.aixm_object.hjid
-- composed CircleSectorPropertyType for sector_description
left join procedure.crclngrstrctntp_sctrdscrptn_link procedure_idjqnn on procedure.circlingrestriction_o.hjid = procedure_idjqnn.circlingrestriction_o_hjid
left join aixm.aixm_property aixm_property_mpamfl on procedure_idjqnn.sectordescription_hjid = aixm_property_mpamfl.hjid
-- composed AIXMSurfacePropertyType for restriction_area
left join procedure.crclngrstrctntp_rstrctnar_link procedure_kuyvii on procedure.circlingrestriction_o.hjid = procedure_kuyvii.circlingrestriction_o_hjid
left join gml.aixm_surface_pt_view aixm_surface_pt_view_rcctaa on procedure_kuyvii.restrictionarea_hjid = aixm_surface_pt_view_rcctaa.hjid
;;

