    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from navaids_point.dstnctp_annttn_link join aixm.aixm_property on navaids_point.dstnctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where navaids_point.distance_o.hjid = navaids_point.dstnctp_annttn_link.distance_o_hjid ) as annotation
