    'title', organisation.organisationauthority_p.simple_link_title)),'[]'::jsonb) from airport_heliport.wrkractvttp_spcldtathrt_link join organisation.organisationauthority_p on airport_heliport.wrkractvttp_spcldtathrt_link.specialdateauthority_hjid = organisation.organisationauthority_p.hjid where airport_heliport.workareaactivity_o.hjid = airport_heliport.wrkractvttp_spcldtathrt_link.workareaactivity_o_hjid ) as special_date_authority
from airport_heliport.workareaactivity_p 
inner join aixm.aixm_property on airport_heliport.workareaactivity_p.hjid = aixm.aixm_property.hjid
inner join airport_heliport.workareaactivity_o on airport_heliport.workareaactivity_p.workareaactivity_hjid = airport_heliport.workareaactivity_o.hjid
inner join aixm.aixm_object on airport_heliport.workareaactivity_o.hjid = aixm.aixm_object.hjid
;;

